                date.put("selected_date_verified",false);date.put("url_date_used_as_evidence",false);
                date.put("native_parent_relationship_required",true);
                if(requested.target!=null){
                    CsairCalendar.DateTarget target=requested.target;
                    date.put("observed_year",target.year);date.put("observed_month",target.month);date.put("observed_day",target.day);
                    date.put("month_header_text",target.monthHeaderText);date.put("month_header_dom_path",target.monthHeaderPath);
                    date.put("month_dom_path",target.monthPath);date.put("day_list_dom_path",target.dayListPath);
                    date.put("day_dom_path",target.dayPath);date.put("day_dom_text",target.dayText);
                    date.put("dom_disabled",target.domDisabled);date.put("dom_visible_in_viewport",target.domVisibleInViewport);
                    date.put("zero_height_layout_list",target.zeroHeightDayList);
                    if(requested.ready&&geometry!=null&&nativePickerTitle(frame,geometry,"选择日期")
                            &&nativePickerTitle(frame,geometry,target.monthHeaderText)){
                        PhoneObservation.Node node=calendarNativeDay(frame,geometry,target);
                        if(node!=null){
                            addCapability(clicks,capabilities,node,target.dayPath,target.domId,target.dayText,
                                    "choose_departure_date_from_immutable_owner");
                            Map<String,Object> capability=capabilities.get(capabilities.size()-1);
                            capability.put("observed_iso_date",target.isoDate);
                            capability.put("observed_month_header",target.monthHeaderText);
                            capability.put("observed_month_header_dom_path",target.monthHeaderPath);
                            capability.put("observed_month_dom_path",target.monthPath);
                            capability.put("native_target_semantics","same_frame_month_heading_then_list_direct_day");
                            capability.put("native_tree_path",node.nativeTreePath);
                            capability.put("native_parent_class",node.nativeParentClass);
                            capability.put("native_month_heading_path",calendarMonthHeading(frame,target.monthHeaderText).nativeTreePath);
                            capability.put("native_parent_relationship_claimed",true);
                        }
                    }
                }
                evidence.put("observed_calendar",date);
                evidence.put("document_content_pending",calendar.headerOnly);
                evidence.put("query_control_withheld",true);
                evidence.put("underlying_form_capabilities_withheld",true);
            }else if(picker!=null){
                phase=geometry==null?"official_city_picker_geometry_pending":"official_city_picker";
                evidence.put("observed_city_picker",picker.evidence());
                String expected="departure".equals(picker.kind)?goal.fromCity:goal.toCity;
                evidence.put("requested_city_from_immutable_owner",expected);
                evidence.put("selected_city_verified",false);
                CsairCityPicker.City city=picker.city(expected);
                if(geometry!=null&&city!=null&&nativePickerTitle(frame,geometry,picker.title)){
                    PhoneObservation.Node target=uniqueNative(frame,geometry,"","android.view.View",expected,
                            Collections.singletonList(expected),false);
                    if(target!=null)addCapability(clicks,capabilities,target,city.path,"",expected,
                            "choose_"+picker.kind+"_city_from_immutable_owner");
                }
                // The still-visible form behind this picker never receives a capability.
                evidence.put("underlying_form_capabilities_withheld",true);
                evidence.put("query_control_withheld",true);
            }else if(form!=null){
                // Require the form root's complete visible ancestry as well as
                // the provider's field-to-tab ancestry. Hidden sibling IDs remain data.
                need(visibleAncestors(byPath.get(form.formPath),byPath),"form ancestor is not currently visible");
                phase=geometry==null?"official_query_form_geometry_pending":"official_query_form";
                observedForm=form;evidence.put("observed_query_form",form.evidence());
                if(geometry!=null){
                    Map<String,Object> depRead=nativeFormReadback(frame,geometry,form.departure);
                    Map<String,Object> arrRead=nativeFormReadback(frame,geometry,form.arrival);
                    Map<String,Object> dateRead=nativeFormReadback(frame,geometry,form.departureDate);
                    if(depRead!=null)readbacks.put("departure",depRead);
                    if(arrRead!=null)readbacks.put("arrival",arrRead);
                    if(dateRead!=null)readbacks.put("date",dateRead);
                    if(!form.query.disabled){
                        PhoneObservation.Node q=uniqueNative(frame,geometry,form.query.id,"android.widget.Button",
                                "查询",form.query.visibleTexts,false);
                        if(q!=null){
                            List<Map<String,Object>> isolated=new ArrayList<Map<String,Object>>();
                            addCapability(new HashSet<String>(),isolated,q,form.query.path,form.query.id,"查询",WebFlightProgress.QUERY);
                            query=isolated.get(0);
                        }
                    }

                    addFormControl(frame,geometry,form.departure,"choose_departure_city",clicks,capabilities);
                    addFormControl(frame,geometry,form.arrival,"choose_arrival_city",clicks,capabilities);
                    addFormControl(frame,geometry,form.departureDate,"choose_departure_date",clicks,capabilities);
                }
                // A current query control is data until the actual model selection
                // chain confirms both cities and the full calendar date.
                evidence.put("native_form_field_readback",readbacks);
                evidence.put("observed_query_control",query);
                evidence.put("query_control_withheld",true);
                evidence.put("query_control_withheld_reason","actual model selection chain not yet applied");
            }
        }
        JSONObject semantic=new JSONObject().put("native_url",receipt.url).put("instance",receipt.instance)
                .put("epoch",receipt.epoch).put("phase",phase)
                .put("native_geometry_sha256",geometry==null?JSONObject.NULL:geometry.fingerprint)
                .put("capabilities",new JSONArray(capabilities));
        if(evidence.containsKey("observed_query_form"))semantic.put("form",new JSONObject((Map<?,?>)evidence.get("observed_query_form")));
        if(evidence.containsKey("observed_city_picker"))semantic.put("city_picker",new JSONObject((Map<?,?>)evidence.get("observed_city_picker")));
        if(evidence.containsKey("observed_calendar"))semantic.put("calendar",new JSONObject((Map<?,?>)evidence.get("observed_calendar")));
        pageKey=WebEvidenceJson.sha(semantic.toString());
        evidence.put("capabilities_withheld_reason",geometry==null?"actual native/visual-viewport bracket absent":
                clicks.isEmpty()?"no unique visible native AX target matches the actual page semantics":null);
        evidence.put("phase",phase);evidence.put("allowed_click_ids",new ArrayList<String>(clicks));
        evidence.put("native_ax_capabilities",capabilities);
        evidence.put("semantic_region_sha256",pageKey);evidence.put("flight_result_inferred",false);
        evidence.put("next_goal",clicks.isEmpty()?"当前页面没有已验证的只读控件；等待加载或报告未完成。":
                "official_home".equals(phase)?"选择实际『机票预订』入口，再观察公开查询表单。":
                "official_city_picker".equals(phase)?"仅选择本次原始指令中对应的城市；使用原生语义点击，选择结果须下一帧重新核对。":
                "official_calendar".equals(phase)?"仅用本帧原生节点选择原始指令的完整年月日；选择结果须下一帧重新核对，不能把日历显示当作已选择。":
                "只用本帧原生节点选择出发城市、到达城市或出发日期；查询仍等待完整目标值验证。");
        evidence.put("missing",java.util.Arrays.asList("actual_selected_city_confirmation","actual_selected_complete_date_confirmation",
                "model_bound_public_query_dispatch","actual_same_record_flight_result"));
        return new WebFlightDomain(task,goal,auth,frame,receipt,phase,pageKey,clicks,edits,evidence,
                observedForm,readbacks,query,capabilities);
    }
    static WebFlightDomain waiting(String task,WebFlightGoal goal,TaskAuthorization.Gate auth,PhoneObservation frame,
                                   WebEvidenceReceipt receipt,String bindingSha)throws Exception{
        need(goal!=null&&auth!=null&&task.equals(auth.taskId)&&goal.ownerSha256.equals(auth.authorization.instructionSha256),
                "same immutable flight owner required for metadata wait");
        need(("unavailable".equals(receipt.status)||"state_changed".equals(receipt.status))&&!receipt.cleanupKnown
                &&frame!=null&&WebEvidenceProtocol.HELPER_PACKAGE.equals(frame.packageName)
                &&frame.windowMetadata!=null&&"observed".equals(frame.windowMetadata.status)
                &&Integer.valueOf(1).equals(frame.windowMetadata.type)&&frame.windowMetadata.displayId!=null
                &&frame.windowMetadata.displayId==receipt.displayId&&frame.windowId==receipt.windowId
                &&frame.backgroundGeneration!=null&&bindingSha.equals(receipt.bindingSha),"same live AX/helper wait domain");
        Map<String,Object> evidence=new LinkedHashMap<String,Object>();
        evidence.put("schema",SCHEMA);evidence.put("task_id",task);evidence.put("owner_sha256",goal.ownerSha256);
        evidence.put("contract_sha256",goal.contractSha256);evidence.put("authorization_sha256",auth.authorization.sha256);
        evidence.put("observation_id",frame.id);evidence.put("observation_state_sha256",frame.treeSha256);
        evidence.put("binding_sha256",bindingSha);evidence.put("background_generation",frame.backgroundGeneration);
        evidence.put("display_id",receipt.displayId);evidence.put("window_id",receipt.windowId);
        evidence.put("webview_instance",receipt.instance);evidence.put("navigation_epoch",receipt.epoch);
        evidence.put("phase","official_page_capture_pending");evidence.put("capture_status",receipt.status);
        evidence.put("capture_callback",receipt.callback());evidence.put("allowed_click_ids",Collections.emptyList());
        evidence.put("native_ax_capabilities",Collections.emptyList());evidence.put("grants_tool_authority",false);
        evidence.put("query_executed",false);evidence.put("business_verified",false);evidence.put("cleanup_known",false);
        evidence.put("next_goal","官网证据尚未稳定；只可等待或报告未完成，不能点击、输入或宣称查询成功。");
        String key=WebEvidenceJson.sha(receipt.callback().toString()+"\\n"+frame.id);
        return new WebFlightDomain(task,goal,auth,frame,receipt,"official_page_capture_pending",key,
                Collections.<String>emptySet(),Collections.<String,String>emptyMap(),evidence,
                null,Collections.<String,Map<String,Object>>emptyMap(),null,Collections.<Map<String,Object>>emptyList());
    }
    Map<String,Object> evidence(){return new LinkedHashMap<String,Object>(proof);}
    Set<String> clicks(Set<String> original){Set<String> out=new HashSet<String>(original);out.retainAll(clickIds);return out;}
    Set<String> edits(Set<String> original){Set<String> out=new HashSet<String>(original);out.retainAll(editValues.keySet());return out;}
    <T> Map<String,T> noNodeActions(Map<String,T> original){return Collections.emptyMap();}
    Set<String> openPackages(Set<String> original){return Collections.emptySet();}
    Set<String> toolMask(Set<String> original){
        Set<String> allowed=new HashSet<String>(java.util.Arrays.asList("done","wait"));
        if(!clickIds.isEmpty())allowed.add("click");if(!editValues.isEmpty())allowed.add("type");
        if(original!=null)allowed.retainAll(original);return allowed;
    }
    void requireCurrent(ActionDecision action){
        need(action!=null&&observationId.equals(action.observationId)&&WebEvidenceProtocol.HELPER_PACKAGE.equals(action.packageName),"web action belongs to another frame");
        if("done".equals(action.action)){need(!"success".equals(action.status),"actual flight results have not been independently verified");return;}
        if("wait".equals(action.action))return;
        if("click".equals(action.action)){need(action.nodeId!=null&&clickIds.contains(action.nodeId),"web click is not a proved current public navigation target");return;}
        if("type".equals(action.action)){need(action.nodeId!=null&&editValues.containsKey(action.nodeId)&&editValues.get(action.nodeId).equals(action.text),"web input differs from exact OWNER field");return;}
        throw new IllegalArgumentException("当前官网页面没有该只读操作的真实证据");
    }
    private static boolean nativePickerTitle(PhoneObservation frame,WebNativeGeometry geometry,String title){
        List<PhoneObservation.Node> matches=new ArrayList<PhoneObservation.Node>();
        for(PhoneObservation.Node node:frame.nodes)if(title.equals(node.text))matches.add(node);
        if(matches.size()!=1)return false;
        PhoneObservation.Node node=matches.get(0);
        return WebEvidenceProtocol.HELPER_PACKAGE.equals(node.packageName)&&"android.widget.TextView".equals(node.className)
                &&node.enabled&&!node.clickable&&!node.editable&&!node.password&&!node.scrollable
                &&node.observedAppTreeSignature!=null&&node.observedAppTreeSignature.matches("[0-9a-f]{64}")
                &&geometry.contains(node.bounds.left,node.bounds.top,node.bounds.right,node.bounds.bottom)
                &&inside(frame.windowMetadata.rootBounds(),node)&&inside(frame.windowMetadata.windowBounds(),node)
                &&node.bounds.left>=0&&node.bounds.top>=0&&node.bounds.right<=frame.width&&node.bounds.bottom<=frame.height;
    }
    private static PhoneObservation.Node calendarMonthHeading(PhoneObservation frame,String title){
        PhoneObservation.Node found=null;
        for(PhoneObservation.Node node:frame.nodes)if(title.equals(node.text)){
            if(found!=null)return null;found=node;
        }
        return found;
    }
    private static PhoneObservation.Node calendarNativeDay(PhoneObservation frame,WebNativeGeometry geometry,
                                                            CsairCalendar.DateTarget target)throws Exception{
        PhoneObservation.Node day=uniqueNative(frame,geometry,target.domId,"android.view.View",target.dayText,
                Collections.singletonList(target.dayText),false);
        PhoneObservation.Node heading=calendarMonthHeading(frame,target.monthHeaderText);
        if(day==null||heading==null||day.nativeTreePath==null||heading.nativeTreePath==null
                ||!"android.widget.ListView".equals(day.nativeParentClass)
                ||!nativePickerTitle(frame,geometry,target.monthHeaderText))return null;
        String dayPath=day.nativeTreePath,headerPath=heading.nativeTreePath;
        int daySlash=dayPath.lastIndexOf('/'),headerSlash=headerPath.lastIndexOf('/');
        if(daySlash<0||headerSlash<0)return null;
        String listPath=dayPath.substring(0,daySlash);int listSlash=listPath.lastIndexOf('/');
        if(listSlash<0||!listPath.substring(0,listSlash).equals(headerPath.substring(0,headerSlash)))return null;
        int listIndex=Integer.parseInt(listPath.substring(listSlash+1));
        int headerIndex=Integer.parseInt(headerPath.substring(headerSlash+1));
        // The month heading and immediately following native ListView share an actual parent.
        return listIndex==headerIndex+1?day:null;
    }
    /** Each known DOM field string must also occur in this same native field's
     * own label or real bounded descendant sources. A clickable label alone is
     * insufficient to prove the selected value. No CSS coordinate is consulted. */
    private static Map<String,Object> nativeFormReadback(PhoneObservation frame,WebNativeGeometry geometry,
                                                        CsairFlightForm.Control control)throws Exception{
        if(control.disabled)return null;
        PhoneObservation.Node root=uniqueNative(frame,geometry,control.id,"android.view.View",
                control.requiredLabel,control.visibleTexts,true);
        if(root==null)return null;
        Set<String> wanted=new HashSet<String>(),observed=new HashSet<String>();
        for(String value:control.visibleTexts)wanted.add(WebEvidenceJson.sha(value));
        List<String> nativePaths=new ArrayList<String>();
        for(String value:new String[]{root.text,root.description})if(!value.isEmpty()){
            String sha=WebEvidenceJson.sha(value);if(!wanted.contains(sha))return null;observed.add(sha);
        }
        ObservedChildText.Result child=root.childText;
        if("derived".equals(child.status)){
            if(child.truncated||child.sources.isEmpty()||!child.rootSignature.matches("[0-9a-f]{64}")
                    ||!child.bind(child.rootSignature).equals(root.observedAppTreeSignature))return null;
            for(ObservedChildText.Source source:child.sources){
                if(!source.descendantPath.matches("[0-9]+(?:/[0-9]+){0,3}")
                        ||!("text".equals(source.property)||"description".equals(source.property))
                        ||source.nodeSignature==null||!source.nodeSignature.matches("[0-9a-f]{64}")
                        ||!wanted.contains(source.textSha256))return null;
                observed.add(source.textSha256);
            }
        }
        if(root.nativeTreePath!=null)for(PhoneObservation.Node node:frame.nodes){
            if(node.nativeTreePath==null||!node.nativeTreePath.startsWith(root.nativeTreePath+"/"))continue;
            if(!WebEvidenceProtocol.HELPER_PACKAGE.equals(node.packageName)||node.password||node.editable
                    ||node.observedAppTreeSignature==null||!node.observedAppTreeSignature.matches("[0-9a-f]{64}")
                    ||!geometry.contains(node.bounds.left,node.bounds.top,node.bounds.right,node.bounds.bottom)
                    ||!inside(new int[]{root.bounds.left,root.bounds.top,root.bounds.right,root.bounds.bottom},node))return null;
            for(String value:new String[]{node.text,node.description})if(!value.isEmpty()){
                String sha=WebEvidenceJson.sha(value);if(!wanted.contains(sha))return null;observed.add(sha);
            }
            nativePaths.add(node.nativeTreePath);
        }
        if(!observed.equals(wanted))return null;
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("node_id",root.id);out.put("native_view_id",root.viewId);out.put("native_class",root.className);
        out.put("node_app_tree_sha256",root.observedAppTreeSignature);out.put("native_tree_path",root.nativeTreePath);
        out.put("native_descendant_paths",nativePaths);out.put("dom_path",control.path);
        out.put("observed_literal_texts",control.visibleTexts);out.put("all_dom_field_strings_observed_natively",true);
        out.put("derived_sources_complete",child.sourcesComplete);out.put("dom_rect_used_as_target",false);
        return Collections.unmodifiableMap(out);
    }
    private static void addFormControl(PhoneObservation frame,WebNativeGeometry geometry,CsairFlightForm.Control control,
                                       String purpose,Set<String> clicks,List<Map<String,Object>> capabilities)throws Exception{
        if(control.disabled)return;
        PhoneObservation.Node node=uniqueNative(frame,geometry,control.id,"android.view.View",
                control.requiredLabel,control.visibleTexts,true);
        if(node!=null)addCapability(clicks,capabilities,node,control.path,control.id,control.requiredLabel,purpose);
    }
    private static void addCapability(Set<String> clicks,List<Map<String,Object>> capabilities,PhoneObservation.Node node,
                                      String domPath,String domId,String label,String purpose){
        need(clicks.add(node.id),"one native AX node cannot stand for two DOM controls");
        Map<String,Object> value=new LinkedHashMap<String,Object>();
        value.put("node_id",node.id);value.put("node_app_tree_sha256",node.observedAppTreeSignature);
        value.put("native_view_id",node.viewId);value.put("native_class",node.className);
        value.put("native_bounds",java.util.Arrays.asList(node.bounds.left,node.bounds.top,node.bounds.right,node.bounds.bottom));
        value.put("native_label",node.label());value.put("dom_path",domPath);value.put("dom_id",domId);
        value.put("expected_control_label",label);value.put("purpose",purpose);
        value.put("target_source","same_frame_native_accessibility_node_id");
        value.put("dom_rect_used_as_target",false);value.put("child_label_sources_complete",node.childText.sourcesComplete);
        capabilities.add(value);
    }
    private static PhoneObservation.Node uniqueNative(PhoneObservation frame,WebNativeGeometry geometry,
            String resourceId,String nativeClass,String label,List<String> knownTexts,boolean derivedAllowed)throws Exception{
        List<PhoneObservation.Node> candidates=new ArrayList<PhoneObservation.Node>();
        for(PhoneObservation.Node node:frame.nodes){
            boolean sameId=resourceId.isEmpty()?node.viewId.isEmpty()&&label.equals(node.label()):resourceId.equals(node.viewId);
            if(sameId)candidates.add(node);
        }
        // Count first, before state filtering: a disabled or otherwise invalid
        // duplicate does not silently disappear to create apparent uniqueness.
        if(candidates.size()!=1)return null;
        PhoneObservation.Node node=candidates.get(0);
        if(!WebEvidenceProtocol.HELPER_PACKAGE.equals(node.packageName)||!nativeClass.equals(node.className)
                ||!node.clickable||!node.enabled||node.editable||node.password||node.scrollable
                ||node.observedAppTreeSignature==null||!node.observedAppTreeSignature.matches("[0-9a-f]{64}")
                ||!geometry.contains(node.bounds.left,node.bounds.top,node.bounds.right,node.bounds.bottom)
                ||!inside(frame.windowMetadata.rootBounds(),node)||!inside(frame.windowMetadata.windowBounds(),node)
                ||node.bounds.left<0||node.bounds.top<0||node.bounds.right>frame.width||node.bounds.bottom>frame.height)return null;
        String own=node.text.isEmpty()?node.description:node.text;
        if(!own.isEmpty())return label.equals(own)?node:null;
        if(!derivedAllowed)return null;
        ObservedChildText.Result child=node.childText;
        if(!"derived".equals(child.status)||child.truncated||child.sources.isEmpty()
                ||!child.rootSignature.matches("[0-9a-f]{64}")
                ||!child.bind(child.rootSignature).equals(node.observedAppTreeSignature))return null;
        Set<String> hashes=new HashSet<String>();for(String value:knownTexts)hashes.add(WebEvidenceJson.sha(value));
        boolean required=false;
        for(ObservedChildText.Source source:child.sources){
            if(!source.descendantPath.matches("[0-9]+(?:/[0-9]+){0,3}")
                    ||!("text".equals(source.property)||"description".equals(source.property))
                    ||source.nodeSignature==null||!source.nodeSignature.matches("[0-9a-f]{64}")
                    ||!hashes.contains(source.textSha256))return null;
            if(WebEvidenceJson.sha(label).equals(source.textSha256))required=true;
        }
        // The real collector de-duplicates identical visible strings. Its
        // sourcesComplete=false for such duplicates is retained in the proof;
        // it is not a claim that all field values have been read.
        return required?node:null;
    }
    private static boolean inside(int[] bounds,PhoneObservation.Node node){
        return bounds!=null&&bounds.length==4&&bounds[0]<=node.bounds.left&&bounds[1]<=node.bounds.top
                &&node.bounds.right<=bounds[2]&&node.bounds.bottom<=bounds[3];
    }
    private static boolean visibleAncestors(JSONObject node,Map<String,JSONObject> byPath)throws Exception{
        if(node==null)return false;
        while(true){
            if(!Boolean.TRUE.equals(node.get("visible_in_viewport")))return false;
            Object parent=node.get("parent_path");
            if(parent==JSONObject.NULL)return "0".equals(node.getString("path"));
            if(!(parent instanceof String)||(node=byPath.get(parent))==null)return false;
        }
    }
    private static double finite(Object value){
        need(value instanceof Number,"actual numeric DOM geometry required");double n=((Number)value).doubleValue();
        need(!Double.isNaN(n)&&!Double.isInfinite(n),"finite DOM geometry required");return n;
    }
    private static void need(boolean ok,String why){WebEvidenceJson.need(ok,why);}
}

package org.trillionnium.hepta.local;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One lease's actual model selection and one public-query attempt.
 * The only constructors are fed by the original executor outcome and fresh
 * captured domains. A requested city/year or a planned click is never readback.
 */
final class WebFlightProgress {
    static final String QUERY="submit_public_flight_query_once";
    private final WebFlightDomain anchor;
    private final Confirmation departure,arrival,date;
    private final Pending pending;
    private final Query query;

    private WebFlightProgress(WebFlightDomain anchor,Confirmation departure,Confirmation arrival,
                              Confirmation date,Pending pending,Query query){
        this.anchor=anchor;this.departure=departure;this.arrival=arrival;
        this.date=date;this.pending=pending;this.query=query;
    }
    static WebFlightProgress begin(WebFlightDomain frame){
        need(frame!=null,"actual flight domain required");
        return new WebFlightProgress(frame,null,null,null,null,null);
    }
    boolean matches(WebFlightDomain frame){
        return frame!=null&&anchor.taskId.equals(frame.taskId)&&anchor.ownerSha.equals(frame.ownerSha)
                &&anchor.contractSha.equals(frame.contractSha)&&anchor.authorizationSha.equals(frame.authorizationSha)
                &&anchor.bindingSha.equals(frame.bindingSha)&&anchor.generation.equals(frame.generation)
                &&anchor.instance.equals(frame.instance)&&anchor.displayId==frame.displayId
                &&anchor.windowId==frame.windowId&&frame.epoch>=anchor.epoch;
    }
    boolean hasConfirmedCities(){return departure!=null&&arrival!=null;}
    boolean selectionPending(){return pending!=null;}
    boolean queryAttempted(){return query!=null;}
    boolean queryDispatched(){return query!=null&&query.outcomeObserved&&query.nativeCallEntered
            &&query.accepted&&query.dispatched&&!query.stale;}
    boolean selectionConfirmed(String kind,WebFlightDomain now){
        need(matches(now),"selection belongs to another flight lease");
        Confirmation value="departure".equals(kind)?departure:"arrival".equals(kind)?arrival:date;
        return value!=null&&now.form!=null&&now.nativeValueMatches(kind)
                &&literalMatches(kind,now)&&now.captureStarted>=value.afterCaptureStarted&&now.epoch>=value.afterEpoch;
    }
    boolean queryReady(WebFlightDomain now){
        return matches(now)&&pending==null&&query==null&&now.form!=null
                &&now.form.adults==1&&now.form.children==0&&now.form.infants==0
                &&selectionConfirmed("departure",now)&&selectionConfirmed("arrival",now)
                &&selectionConfirmed("date",now)&&now.queryCandidate!=null;
    }
    /** Saved durably by the caller before any possible native query invocation. */
    WebFlightProgress reserveQuery(WebFlightDomain before,ActionDecision action,String run){
        need(matches(before)&&queryReady(before)&&pending==null,"actual flight selections are not query-ready");
        before.requireCurrent(action);
        need("click".equals(action.action)&&QUERY.equals(before.purpose(action.nodeId))
                &&run!=null&&run.matches("[0-9a-f]{32}"),"one model-bound query control required");
        return new WebFlightProgress(anchor,departure,arrival,date,null,new Query(before,action,run));
    }
    boolean isQueryAction(ActionDecision action,String run){
        return query!=null&&action!=null&&query.run.equals(run)&&"click".equals(action.action)
                &&query.before.observationId.equals(action.observationId)&&query.action.nodeId.equals(action.nodeId);
    }
    boolean reservedFor(WebFlightDomain before,ActionDecision action,String run){
        return query!=null&&!query.outcomeObserved&&matches(before)&&query.run.equals(run)
                &&query.before.observationId.equals(before.observationId)
                &&query.action.nodeId.equals(action.nodeId)&&"click".equals(action.action);
    }
    /** This consumes the actual result, including false/unknown dispatch facts. */
    WebFlightProgress outcome(WebFlightDomain before,ActionDecision action,String run,
            boolean accepted,boolean dispatched,boolean stale,boolean nativeQueryCallEntered,long start,long end){
        need(matches(before)&&action!=null&&run!=null&&run.matches("[0-9a-f]{32}")
                &&before.observationId.equals(action.observationId)
                &&before.captureEnded>=0&&before.captureEnded<=start&&start<=end,
                "actual same-lease model dispatch and monotonic clocks required");
        if(!"click".equals(action.action))return this;
        before.requireCurrent(action);
        String purpose=before.purpose(action.nodeId);
        need(purpose!=null,"actual observed flight capability required");
        if(QUERY.equals(purpose)){
            need(reservedFor(before,action,run),"query reservation missing or already consumed");
            need(!accepted||nativeQueryCallEntered,"accepted query requires actual native call entry");
            return new WebFlightProgress(anchor,departure,arrival,date,null,
                    new Query(query,accepted,dispatched,stale,nativeQueryCallEntered,start,end));
        }
        need(query==null,"no page action after a query attempt");
        if(!accepted||!dispatched||stale)return this;
        String kind=selectionKind(purpose);
        if(kind!=null){
            need(pending==null,"prior flight selection has no actual readback yet");
            if("date".equals(kind))need(hasConfirmedCities()
                    &&before.goal.departureDate.toString().equals(before.capability(action.nodeId).get("observed_iso_date"))
                    &&Boolean.TRUE.equals(before.capability(action.nodeId).get("native_parent_relationship_claimed")),
                    "full literal calendar date and actual native month/list relation required");
            return new WebFlightProgress(anchor,departure,arrival,"date".equals(kind)?date:null,
                    new Pending(before,action,run,kind,start,end),null);
        }
        // Reopening a field invalidates its older confirmation even if the next
        // page has not loaded. An old year cannot survive a new date edit.
        if("choose_departure_city".equals(purpose))
            return new WebFlightProgress(anchor,null,arrival,null,null,null);
        if("choose_arrival_city".equals(purpose))
            return new WebFlightProgress(anchor,departure,null,null,null,null);
        if("choose_departure_date".equals(purpose))
            return new WebFlightProgress(anchor,departure,arrival,null,null,null);
        return this;
    }
    /** Fresh capture only. No click, retry, URL construction or OWNER rewriting. */
    WebFlightProgress observed(WebFlightDomain now){
        need(matches(now),"flight progress cannot move to another lease, window or identity");
        if(now.captureStarted<0)return this;
        if(query!=null){
            if(query.outcomeObserved&&query.after==null&&now.captureStarted>=query.end)
                return new WebFlightProgress(anchor,departure,arrival,date,null,new Query(query,now));
            return this;
        }
        Confirmation dep=departure,arr=arrival,day=date;
        if(now.form!=null){
            if(dep!=null&&!literalMatches("departure",now))dep=null;
            if(arr!=null&&!literalMatches("arrival",now))arr=null;
            if(day!=null&&!literalMatches("date",now))day=null;
        }
        Pending wait=pending;
        if(wait!=null&&now.form!=null&&now.captureStarted>=wait.end&&now.epoch>=wait.before.epoch
                &&now.nativeValueMatches(wait.kind)&&literalMatches(wait.kind,now)){
            Confirmation confirmed=new Confirmation(wait,now);
            if("departure".equals(wait.kind))dep=confirmed;
            else if("arrival".equals(wait.kind))arr=confirmed;
            else day=confirmed;
            wait=null;
        }
        if(dep==departure&&arr==arrival&&day==date&&wait==pending)return this;
        return new WebFlightProgress(anchor,dep,arr,day,wait,null);
    }
    Map<String,Object> evidence(WebFlightDomain now){
        need(matches(now),"flight evidence scope");
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("schema","hepta.csair-model-query-progress.v1");
        out.put("task_id",anchor.taskId);out.put("owner_sha256",anchor.ownerSha);
        out.put("contract_sha256",anchor.contractSha);out.put("authorization_sha256",anchor.authorizationSha);
        out.put("binding_sha256",anchor.bindingSha);out.put("background_generation",anchor.generation);
        out.put("webview_instance",anchor.instance);out.put("display_id",anchor.displayId);out.put("window_id",anchor.windowId);
        out.put("departure_selection",departure==null?null:departure.evidence);
        out.put("arrival_selection",arrival==null?null:arrival.evidence);
        out.put("complete_date_selection",date==null?null:date.evidence);
        out.put("selection_readback_pending",pending==null?null:pending.evidence);
        out.put("current_departure_value_verified",selectionConfirmed("departure",now));
        out.put("current_arrival_value_verified",selectionConfirmed("arrival",now));
        out.put("current_complete_date_verified",selectionConfirmed("date",now));
        out.put("query_ready",queryReady(now));out.put("query_attempted",queryAttempted());
        out.put("query_native_dispatch_confirmed",queryDispatched());
        out.put("query_attempt",query==null?null:query.evidence());
        out.put("query_retry_permitted",false);out.put("results_verified",false);
        out.put("business_verified",false);out.put("grants_tool_authority",false);
        return Collections.unmodifiableMap(out);
    }
    private boolean literalMatches(String kind,WebFlightDomain now){
        if(now.form==null)return false;
        if("departure".equals(kind))return anchor.goal.fromCity.equals(now.form.departureCityLiteral);
        if("arrival".equals(kind))return anchor.goal.toCity.equals(now.form.arrivalCityLiteral);
        return "date".equals(kind)&&now.form.displayedMonth!=null&&now.form.displayedDay!=null
                &&now.form.displayedMonth.intValue()==anchor.goal.departureDate.getMonthValue()
                &&now.form.displayedDay.intValue()==anchor.goal.departureDate.getDayOfMonth()
                &&(now.form.displayedWeekday==null||weekday(anchor.goal.departureDate.getDayOfWeek().getValue()).equals(now.form.displayedWeekday)
                        ||anchor.goal.departureDate.getDayOfWeek().getValue()==7&&"周天".equals(now.form.displayedWeekday));
    }
    private static String weekday(int day){return "周"+new String[]{"一","二","三","四","五","六","日"}[day-1];}
    private static String selectionKind(String purpose){
        if("choose_departure_city_from_immutable_owner".equals(purpose))return "departure";
        if("choose_arrival_city_from_immutable_owner".equals(purpose))return "arrival";
        if("choose_departure_date_from_immutable_owner".equals(purpose))return "date";
        return null;
    }
    private static final class Pending {
        final WebFlightDomain before;final ActionDecision action;final String run,kind;final long start,end;
        final Map<String,Object> evidence;
        Pending(WebFlightDomain before,ActionDecision action,String run,String kind,long start,long end){
            this.before=before;this.action=action;this.run=run;this.kind=kind;this.start=start;this.end=end;
            Map<String,Object> out=dispatch(before,action,run,start,end);
            out.put("selection_kind",kind);out.put("accepted",true);out.put("dispatched",true);out.put("stale",false);
            out.put("source_capability",before.capability(action.nodeId));
            out.put("after_form_verified",false);evidence=Collections.unmodifiableMap(out);
        }
    }
    private static final class Confirmation {
        final long afterCaptureStarted,afterEpoch;final Map<String,Object> evidence;
        Confirmation(Pending pending,WebFlightDomain after){
            afterCaptureStarted=after.captureStarted;afterEpoch=after.epoch;
            Map<String,Object> out=new LinkedHashMap<String,Object>(pending.evidence);
            out.put("after_observation_id",after.observationId);out.put("after_dom_sha256",after.domSha);
            out.put("after_native_url",after.url);out.put("after_navigation_epoch",after.epoch);
            out.put("after_capture_started_elapsed_ms",after.captureStarted);
            out.put("after_form_verified",true);out.put("native_field_readback",after.nativeReadbacks.get(pending.kind));
            out.put("selected_literal_value","departure".equals(pending.kind)?after.form.departureCityLiteral:
                    "arrival".equals(pending.kind)?after.form.arrivalCityLiteral:
                            pending.before.goal.departureDate.toString());
            out.put("displayed_year",null);
            out.put("year_source","date".equals(pending.kind)?"actual_clicked_calendar_month_header":null);
            out.put("year_from_url_or_today",false);evidence=Collections.unmodifiableMap(out);
        }
    }
    private static final class Query {
        final WebFlightDomain before,after;final ActionDecision action;final String run;
        final boolean outcomeObserved,accepted,dispatched,stale,nativeCallEntered;final long start,end;
        Query(WebFlightDomain before,ActionDecision action,String run){
            this.before=before;this.action=action;this.run=run;after=null;outcomeObserved=false;
            accepted=false;dispatched=false;stale=false;nativeCallEntered=false;start=-1;end=-1;
        }
        Query(Query original,boolean accepted,boolean dispatched,boolean stale,boolean entered,long start,long end){
            before=original.before;action=original.action;run=original.run;after=null;outcomeObserved=true;
            this.accepted=accepted;this.dispatched=dispatched;this.stale=stale;nativeCallEntered=entered;this.start=start;this.end=end;
        }
        Query(Query original,WebFlightDomain after){
            before=original.before;action=original.action;run=original.run;this.after=after;outcomeObserved=original.outcomeObserved;
            accepted=original.accepted;dispatched=original.dispatched;stale=original.stale;
            nativeCallEntered=original.nativeCallEntered;start=original.start;end=original.end;
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=dispatch(before,action,run,start,end);
            out.put("source","actual_controller_query_reservation_and_executor_outcome");
            out.put("reservation_consumed",true);out.put("outcome_observed",outcomeObserved);
            out.put("native_action_click_call_entered",nativeCallEntered);
            out.put("accepted",outcomeObserved?Boolean.valueOf(accepted):null);
            out.put("dispatched",outcomeObserved?Boolean.valueOf(dispatched):null);
            out.put("stale",outcomeObserved?Boolean.valueOf(stale):null);
            out.put("before_verified_form",before.form.evidence());
            out.put("before_selection_chain",before.progressEvidence());
            out.put("query_control",before.capability(action.nodeId));
            out.put("after_observation_id",after==null?null:after.observationId);
            out.put("after_native_url",after==null?null:after.url);
            out.put("after_navigation_epoch",after==null?null:Long.valueOf(after.epoch));
            out.put("after_dom_sha256",after==null?null:after.domSha);
            out.put("after_capture_started_elapsed_ms",after==null?null:Long.valueOf(after.captureStarted));
            out.put("server_query_completed",false);out.put("flight_results_verified",false);
            return Collections.unmodifiableMap(out);
        }
    }
    private static Map<String,Object> dispatch(WebFlightDomain before,ActionDecision action,String run,long start,long end){
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("model_run_id",run);out.put("model_issued",true);out.put("action",action.action);out.put("node_id",action.nodeId);
        out.put("before_observation_id",before.observationId);out.put("before_dom_sha256",before.domSha);
        out.put("before_native_url",before.url);out.put("before_navigation_epoch",before.epoch);
        out.put("before_capture_ended_elapsed_ms",before.captureEnded);
        out.put("dispatch_before_elapsed_ms",start<0?null:Long.valueOf(start));
        out.put("dispatch_after_elapsed_ms",end<0?null:Long.valueOf(end));
        return out;
    }
    private static void need(boolean yes,String reason){WebEvidenceJson.need(yes,reason);}
}

package org.trillionnium.hepta.local;

import android.content.Context;
import android.os.SystemClock;
import org.json.JSONObject;
import org.trillionnium.hepta.local.web.WebFlightGoal;
import org.trillionnium.hepta.local.web.WebShoppingGoal;
import org.trillionnium.hepta.webprotocol.WebTaskPurpose;
import org.trillionnium.hepta.webprotocol.WebEvidenceBinding;
import org.trillionnium.hepta.webprotocol.WebEvidenceProtocol;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.Collections;
import java.util.UUID;

/** One actual OWNER/VD/helper lease; no implicit app selection, network method or UI macro. */
final class WebFlightSession {
    interface Observer { PhoneObservation observe()throws Exception; }
    static final class Cleanup {
        final boolean known;final JSONObject evidence;
        private Cleanup(boolean known,JSONObject evidence){this.known=known;this.evidence=evidence;}
    }
    final String taskId;
    final WebFlightGoal goal;
    final WebTaskPurpose purpose;
    private final JSONObject immutableBinding;
    final TaskAuthorization.Gate authorization;
    private final HeptaAccessibilityService service;
    private final BackgroundSession background;
    private final WebHelperIdentity controller,helper;
    private final WebEvidenceJournal journal;
    private final WebEvidenceClient client;
    private final HeptaAccessibilityService.Cancellation cancellation;
    private final TaskCompletionGate completion;
    private volatile WebTaskDomain domain;
    private volatile boolean retired,cleanupKnown;
    private volatile PhoneObservation current;
    private long dispatchCheckedAt;
    private String dispatchCheckedRun;
    private String dispatchCheckedAction;
    private final File evidence;
    private WebTaskDomain dispatchSource;
    private String dispatchSourceRun,dispatchSourceAction;
    private WebShoppingDomain.Navigation shoppingNavigation;
    private WebFlightProgress flightProgress;
    private final java.util.concurrent.atomic.AtomicBoolean nativeQueryEntered=new java.util.concurrent.atomic.AtomicBoolean();
    private PendingNavigation pendingNavigation;
    private String loadingDocumentKey;
    private long loadingDocumentStarted;
    private int loadingDocumentReadRetries;
    private static final class PendingNavigation {
        final WebShoppingDomain before;final ActionDecision action;final String run;final long start,end;
        final boolean accepted,dispatched,stale;
        PendingNavigation(WebShoppingDomain before,ActionDecision action,String run,
                          HeptaAccessibilityService.ActionOutcome outcome,long start,long end){
            this.before=before;this.action=action;this.run=run;this.start=start;this.end=end;
            this.accepted=outcome.accepted;this.dispatched=outcome.dispatched;this.stale=outcome.stale;
        }
    }

    static void validateSelection(String owner,BackgroundSession.Selection selection){
        WebFlightGoal flight=WebFlightGoal.parse(owner);WebShoppingGoal shopping=WebShoppingGoal.parse(owner);
        boolean selected=selection!=null&&selection.allowedPackages.contains(WebEvidenceProtocol.HELPER_PACKAGE);
        if(flight==null&&shopping==null){
            if(selected)throw new IllegalArgumentException("官网查询需要完整的航班日期、城市或支持的商品目标");return;
        }
        if((flight!=null)==(shopping!=null)||selection==null
                ||!WebEvidenceProtocol.HELPER_PACKAGE.equals(selection.initialPackage)
                ||!selection.allowedPackages.equals(Collections.singletonList(WebEvidenceProtocol.HELPER_PACKAGE)))
            throw new IllegalArgumentException("请启用后台模式，并明确选择官网查询工具作为唯一任务应用");
        try{WebTaskPurpose.fromOwner(owner);}
        catch(Exception invalid){throw new IllegalArgumentException("原始指令不允许本次官网只读查询："+invalid.getMessage(),invalid);}
        if(flight!=null&&!flight.departureNotBefore(LocalDate.now()))
            throw new IllegalArgumentException("查询日期已过去，请指定今天或以后的完整日期");
    }
    static boolean supported(String owner){return WebFlightGoal.parse(owner)!=null||WebShoppingGoal.parse(owner)!=null;}
    static boolean hasUnreleased(Context context){return WebEvidenceJournal.hasUnreleased(context);}

    WebFlightSession(HeptaAccessibilityService service,String task,String owner,TaskAuthorization.Gate authorization,
                     BackgroundSession background,QualificationScopeConfig.FilesRoot filesRoot,File evidence,
                     TaskCompletionGate completion,HeptaAccessibilityService.Cancellation cancellation)throws Exception{
        validateSelection(owner,background==null?null:background.selection);
        purpose=WebTaskPurpose.fromOwner(owner);goal=purpose.flight;
        need(task.equals(authorization.taskId)&&completion!=null,"same task public-page contract required");
        authorization.authorization.requireOwner(owner);authorization.ready();
        need(WebEvidenceBinding.canonical(new JSONObject(purpose.authorization.evidence())).equals(
                WebEvidenceBinding.canonical(new JSONObject(authorization.authorization.evidence()))),
                "actual complete original OWNER authorization differs");
        this.service=service;this.taskId=task;this.authorization=authorization;this.background=background;
        this.cancellation=cancellation;this.completion=completion;this.evidence=evidence;
        background.requireActive();need(background.ownerSha256.equals(purpose.ownerSha256),"background OWNER differs");
        controller=WebHelperIdentity.read(service,WebEvidenceProtocol.CONTROLLER_PACKAGE);
        helper=WebHelperIdentity.read(service,WebEvidenceProtocol.HELPER_PACKAGE);
        WebHelperIdentity.requirePeer(service,controller,helper);
        JSONObject actual=background.evidence();
        JSONObject bg=new JSONObject().put("generation",background.generation).put("display_id",background.displayId())
                .put("display_name",background.displayName).put("boot_count",actual.get("boot_count"))
                .put("created_elapsed_ms",background.createdElapsed).put("expires_elapsed_ms",background.expiresElapsed)
                .put("selected_packages",new org.json.JSONArray(background.selection.allowedPackages));
        String session=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");
        JSONObject attach=new JSONObject().put("task_id",task).put("controller_session_nonce",session)
                .put("owner",owner).put("owner_sha256",purpose.ownerSha256).put("contract_sha256",purpose.contractSha256)
                .put("authorization",new JSONObject(authorization.authorization.evidence()))
                .put("background",bg).put("controller_identity",controller.evidence).put("helper_identity",helper.evidence);
        JSONObject binding=WebEvidenceBinding.fromAttach(attach);
        immutableBinding=new JSONObject(WebEvidenceBinding.canonical(binding));
        journal=WebEvidenceJournal.create(service,filesRoot,evidence,binding);
        client=new WebEvidenceClient(service,controller,helper,binding,new WebEvidenceClient.Guard(){
            public void requireCurrent(boolean cleanup)throws Exception{
                filesRoot.unchanged(service);WebHelperIdentity.requirePeer(service,controller,helper);
                if(!cleanup){
                    need(!retired&&!cancellation.isCancelled(),"web task retired");
                    service.requireTaskAuthorization(taskId,authorization);background.requireActive();
                }
            }
            public boolean cancelled(){return cancellation.isCancelled();}
        },journal);
        JSONObject ownerEvidence=goal!=null?new JSONObject(goal.evidence()):
                new JSONObject(purpose.shopping.canonicalContract()).put("original_owner",purpose.owner);
        record("web-flight-owner.json",ownerEvidence.put("task_id",task)
                .put("goal_kind",purpose.kind).put("site_policy",purpose.policyEvidence())
                .put("site_policy_sha256",purpose.sitePolicySha256).put("initial_url",purpose.initialUrl)
                .put("bootstrap_is_model_query",false)
                .put("task_authorization_sha256",authorization.authorization.sha256).put("binding_sha256",journal.bindingSha)
                .put("task_local_date",LocalDate.now().toString()).put("background_selected_by_owner",true)
                .put("network_process_is_separate_helper",true).put("external_model",false));
    }
    void attach(long deadline)throws Exception{
        need(!retired,"web task retired");long end=Math.min(deadline,SystemClock.elapsedRealtime()+10000);
        client.connect(end);WebEvidenceReceipt response=client.attach(client.newAttach(end));
        record("web-helper-attached.json",response.callback());
    }
    PhoneObservation observe(PhoneObservation initial,Observer observer,long deadline)throws Exception{
        need(!retired&&!cancellation.isCancelled(),"web task retired");
        PhoneObservation before=initial;long captureDeadline=deadline;String loadingAttemptKey=null;
        while(true){
        service.requireBackgroundObservation(taskId,before);
        WebEvidenceReceipt first=client.capture(captureDeadline);
        if("state_changed".equals(first.status)){
            // At most one read-only retry, after a fresh AX window observation; never repeat an action.
            before=observer.observe();service.requireBackgroundObservation(taskId,before);first=client.capture(captureDeadline);
            need("captured".equals(first.status)||"unavailable".equals(first.status)||"state_changed".equals(first.status),
                    "unknown reply after the single evidence retry");
        }
        if("unavailable".equals(first.status)||"state_changed".equals(first.status)){
            PhoneObservation after=observer.observe();service.requireBackgroundObservation(taskId,after);
            return publishWaiting(after,first,"initial_capture_not_stable");
        }
        need("captured".equals(first.status),"actual page capture unavailable");
        PhoneObservation after=observer.observe();service.requireBackgroundObservation(taskId,after);
        WebEvidenceReceipt last=client.capture(captureDeadline);
        if("unavailable".equals(last.status)||"state_changed".equals(last.status))
            return publishWaiting(after,last,"final_capture_not_stable");
        need("captured".equals(last.status),"actual final page capture unavailable");
        String actualLoadingKey=last.instance+"\n"+last.epoch+"\n"+last.url;
        need(loadingAttemptKey==null||loadingAttemptKey.equals(actualLoadingKey),
                "read-only loading retry changed the original instance, URL or navigation epoch");
        boolean stable=sameFrame(before,after)&&first.instance.equals(last.instance)&&first.epoch==last.epoch
                &&first.url.equals(last.url)&&first.domRaw().equals(last.domRaw());
        if(retryLoadingDocument(first,last,after,stable,deadline)){
            loadingAttemptKey=actualLoadingKey;
            captureDeadline=Math.min(deadline,loadingDocumentStarted+6000);
            before=observer.observe();service.requireBackgroundObservation(taskId,before);
            continue;
        }
        need(stable,"AX/DOM bracket changed; no current page capability published");
        WebNativeGeometry firstGeometry=WebNativeGeometry.read(first.capture(),first.dom(),first.displayId,first.windowId);
        WebNativeGeometry lastGeometry=WebNativeGeometry.read(last.capture(),last.dom(),last.displayId,last.windowId);
        need(firstGeometry==null&&lastGeometry==null||firstGeometry!=null&&firstGeometry.same(lastGeometry),
                "native WebView geometry changed across the AX/DOM bracket");
        WebTaskDomain observed=applyNavigation(WebTaskDomain.observed(taskId,purpose,authorization,after,last,immutableBinding));
        record("web-frame-"+after.id+".json",new JSONObject(observed.evidence())
                .put("first_capture_request_nonce",first.callback().getString("request_nonce"))
                .put("last_capture_request_nonce",last.callback().getString("request_nonce"))
                .put("first_ax_observation_id",before.id).put("last_ax_observation_id",after.id)
                .put("ax_dom_capture_is_atomic",false).put("same_lease_epoch_and_equal_dom_bracket",true)
                .put("same_native_geometry_bracket",firstGeometry!=null)
                .put("native_geometry_sha256",lastGeometry==null?JSONObject.NULL:lastGeometry.fingerprint));
        current=after;domain=observed;completion.bindWebDomain(observed);
        dispatchCheckedRun=null;dispatchCheckedAction=null;dispatchCheckedAt=0;
        return after;
        }
    }
    /** Extra observations are bounded and read-only; an entry click is never replayed. */
    private boolean retryLoadingDocument(WebEvidenceReceipt first,WebEvidenceReceipt last,PhoneObservation frame,
                                         boolean stable,long deadline)throws Exception{
        if(goal==null)return false;
        String key=last.instance+"\n"+last.epoch+"\n"+last.url;
        CsairCalendar a=CsairCalendar.read(first.dom()),b=CsairCalendar.read(last.dom());
        boolean bodyPending=a!=null&&a.headerOnly||b!=null&&b.headerOnly;
        boolean bookingPending=WebFlightDomain.bookingBodyPending(first.dom())||WebFlightDomain.bookingBodyPending(last.dom());
        boolean queryPending=flightProgress!=null&&flightProgress.queryDispatched();
        if(!bodyPending&&!bookingPending&&!queryPending&&!(key.equals(loadingDocumentKey)&&!stable))return false;
        need(first.instance.equals(last.instance)&&first.epoch==last.epoch&&first.url.equals(last.url)
                &&first.bindingSha.equals(last.bindingSha)&&first.displayId==last.displayId
                &&first.windowId==last.windowId,"loading observation changed the immutable page domain");
        long now=SystemClock.elapsedRealtime();
        if(!key.equals(loadingDocumentKey)){
            loadingDocumentKey=key;loadingDocumentStarted=now;loadingDocumentReadRetries=0;
        }
        if(loadingDocumentReadRetries>=2||now+250>=Math.min(deadline,loadingDocumentStarted+6000))return false;
        need(!retired&&!cancellation.isCancelled(),"web task retired while waiting for page content");
        loadingDocumentReadRetries++;
        record("web-load-wait-"+UUID.randomUUID().toString().replace("-","")+".json",new JSONObject()
                .put("schema","hepta.web-read-only-content-wait.v1").put("task_id",taskId)
                .put("binding_sha256",journal.bindingSha).put("webview_instance",last.instance)
                .put("navigation_epoch",last.epoch).put("native_url",last.url)
                .put("observation_id",frame.id).put("first_request_nonce",first.callback().getString("request_nonce"))
                .put("last_request_nonce",last.callback().getString("request_nonce"))
                .put("first_dom_sha256",first.domSha).put("last_dom_sha256",last.domSha)
                .put("recognized_calendar_body_pending",bodyPending).put("recognized_booking_body_pending",bookingPending)
                .put("actual_query_awaiting_results",queryPending).put("read_only_retry",loadingDocumentReadRetries)
                .put("maximum_extra_reobservations",2).put("deadline_elapsed_ms",Math.min(deadline,loadingDocumentStarted+6000))
                .put("action_replayed",false).put("model_action_dispatched",false).put("business_verified",false));
        SystemClock.sleep(200);
        need(!retired&&!cancellation.isCancelled(),"web task retired while waiting for page content");
        service.requireTaskAuthorization(taskId,authorization);background.requireActive();
        return true;
    }
    private PhoneObservation publishWaiting(PhoneObservation frame,WebEvidenceReceipt receipt,String reason)throws Exception{
        WebTaskDomain waiting=applyNavigation(WebTaskDomain.waiting(taskId,purpose,authorization,frame,receipt,immutableBinding));
        record("web-frame-"+frame.id+".json",new JSONObject(waiting.evidence()).put("reason",reason)
                .put("capture_metadata_only",true).put("ax_dom_capture_is_atomic",false)
                .put("same_lease_epoch_and_equal_dom_bracket",false));
        current=frame;domain=waiting;completion.bindWebDomain(waiting);
        dispatchCheckedRun=null;dispatchCheckedAction=null;dispatchCheckedAt=0;return frame;
    }
    void beforeModelAction(ActionDecision action,String run,long deadline)throws Exception{
        WebTaskDomain original=domain;PhoneObservation frame=current;
        need(original!=null&&frame!=null&&run!=null&&run.matches("[0-9a-f]{32}"),"current model-bound web action required");
        original.requireCurrent(action);service.requireTaskAuthorization(taskId,authorization);background.requireActive();
        dispatchSource=null;dispatchSourceRun=null;dispatchSourceAction=null;
        if("wait".equals(action.action)||"done".equals(action.action)&&!"success".equals(action.status)){
            // These choices do not manipulate a page. A missing capture never
            // becomes click/type/success authority and never clears the journal.
            dispatchSource=original;dispatchSourceRun=run;dispatchSourceAction=actionKey(action);
            dispatchCheckedRun=run;dispatchCheckedAction=actionKey(action);
            dispatchCheckedAt=SystemClock.elapsedRealtime();
            record("web-dispatch-"+run+".json",new JSONObject(original.evidence()).put("model_run_id",run)
                    .put("model_issued",true).put("action",action.action).put("no_page_effect",true)
                    .put("dispatched",false).put("source","current_restricted_model_choice"));
            return;
        }
        WebEvidenceReceipt fresh=client.capture(deadline);
        need("captured".equals(fresh.status),"document changed before action");
        WebTaskDomain rechecked=applyNavigation(WebTaskDomain.observed(taskId,purpose,authorization,frame,fresh,immutableBinding));
        need(original.instance.equals(rechecked.instance)&&original.epoch==rechecked.epoch
                &&original.pageKey.equals(rechecked.pageKey)&&original.clickIds.equals(rechecked.clickIds)
                &&original.editValues.equals(rechecked.editValues),"page target changed since model observation");
        rechecked.requireCurrent(action);
        if(rechecked.flight!=null&&WebFlightProgress.QUERY.equals(rechecked.flight.purpose(action.nodeId))){
            need(flightProgress!=null&&!nativeQueryEntered.get(),"one query attempt per original lease");
            flightProgress=flightProgress.reserveQuery(rechecked.flight,action,run);
            record("web-query-reservation-"+run+".json",new JSONObject(flightProgress.evidence(rechecked.flight))
                    .put("source","durable_before_native_invocation").put("dispatch_attempted",false));
        }
        dispatchSource=rechecked;dispatchSourceRun=run;dispatchSourceAction=actionKey(action);
        dispatchCheckedRun=run;dispatchCheckedAction=actionKey(action);
        dispatchCheckedAt=SystemClock.elapsedRealtime();
        record("web-dispatch-"+run+".json",new JSONObject(rechecked.evidence())
                .put("model_run_id",run).put("model_issued",true).put("action",action.action)
                .put("node_id",action.nodeId==null?JSONObject.NULL:action.nodeId)
                .put("original_dom_sha256",original.evidence().get("dom_sha256"))
                .put("fresh_capture_request_nonce",fresh.callback().getString("request_nonce"))
                .put("unchanged_semantic_region",true).put("whole_dom_equality_claimed",false)
                .put("dispatched",false).put("source","pre_dispatch_read_only_check_not_action_outcome"));
    }
    void requireDispatch(ActionDecision action,String run){
        WebTaskDomain d=domain;need(!retired&&d!=null&&run!=null&&run.equals(dispatchCheckedRun)
                &&(action.action+"\n"+(action.nodeId==null?"":action.nodeId)).equals(dispatchCheckedAction)
                &&SystemClock.elapsedRealtime()>=dispatchCheckedAt&&SystemClock.elapsedRealtime()-dispatchCheckedAt<=1500,
                "fresh exact web/model action evidence expired");
        d.requireCurrent(action);
    }
    /** Called once immediately before the original ACTION_CLICK platform call,
     * after the service's repeated authority/window/signature checks. No I/O. */
    void beforeNativeClickInvocation(ActionDecision action,String run){
        WebTaskDomain source=dispatchSource,currentDomain=domain;
        boolean queryTarget=currentDomain!=null&&currentDomain.flight!=null
                &&WebFlightProgress.QUERY.equals(currentDomain.flight.purpose(action.nodeId));
        boolean reserved=flightProgress!=null&&flightProgress.isQueryAction(action,run);
        if(!queryTarget&&!reserved)return;
        need(source!=null&&source.flight!=null&&flightProgress!=null
                &&run!=null&&run.equals(dispatchSourceRun)&&actionKey(action).equals(dispatchSourceAction)
                &&flightProgress.reservedFor(source.flight,action,run)
                &&nativeQueryEntered.compareAndSet(false,true),
                "public query native invocation is missing, mismatched or already consumed");
    }
    private static String actionKey(ActionDecision action){return action.action+"\n"+(action.nodeId==null?"":action.nodeId);}
    /** Called with the original executor Outcome, immediately after the actual awaited dispatch. */
    void modelActionOutcome(ActionDecision action,String run,HeptaAccessibilityService.ActionOutcome outcome,
                            long dispatchStarted,long dispatchEnded)throws Exception{
        WebTaskDomain before=dispatchSource;
        try{
        need(!retired&&before!=null&&outcome!=null&&run!=null&&run.equals(dispatchSourceRun)
                &&actionKey(action).equals(dispatchSourceAction)&&action.observationId.equals(before.observationId)
                &&dispatchCheckedAt<=dispatchStarted&&dispatchStarted<=dispatchEnded
                &&dispatchEnded<=SystemClock.elapsedRealtime(),"actual same model action and dispatch clocks required");
        record("web-action-"+run+".json",new JSONObject(before.evidence()).put("model_run_id",run)
                .put("action",action.action).put("node_id",action.nodeId==null?JSONObject.NULL:action.nodeId)
                .put("dispatch_before_elapsed_ms",dispatchStarted).put("dispatch_after_elapsed_ms",dispatchEnded)
                .put("accepted",outcome.accepted).put("dispatched",outcome.dispatched).put("stale",outcome.stale)
                .put("source","actual_controller_executor_outcome").put("model_issued",true).put("business_verified",false));
        if(before.flight!=null&&"click".equals(action.action)){
            need(flightProgress!=null,"actual flight progression missing");
            flightProgress=flightProgress.outcome(before.flight,action,run,outcome.accepted,outcome.dispatched,
                    outcome.stale,nativeQueryEntered.get(),dispatchStarted,dispatchEnded);
            record("web-flight-progress-"+run+".json",new JSONObject(flightProgress.evidence(before.flight))
                    .put("source","actual_controller_executor_outcome"));
        }
        if(before.shopping!=null&&"click".equals(action.action)&&outcome.accepted&&outcome.dispatched&&!outcome.stale){
            need(pendingNavigation==null,"a prior actual product navigation is still unconfirmed");
            pendingNavigation=new PendingNavigation(before.shopping,action,run,outcome,dispatchStarted,dispatchEnded);
        }
        }finally{
            dispatchSource=null;dispatchSourceRun=null;dispatchSourceAction=null;
            dispatchCheckedRun=null;dispatchCheckedAction=null;dispatchCheckedAt=0;
        }
    }
    private WebTaskDomain applyNavigation(WebTaskDomain value)throws Exception{
        if(value.flight!=null){
            if(flightProgress==null)flightProgress=WebFlightProgress.begin(value.flight);
            flightProgress=flightProgress.observed(value.flight);
            return value.withFlightProgress(flightProgress);
        }
        if(value.shopping==null)return value;
        if(shoppingNavigation!=null&&!shoppingNavigation.matches(value.shopping))shoppingNavigation=null;
        if(pendingNavigation!=null&&"official_product_detail".equals(value.phase)){
            PendingNavigation actual=pendingNavigation;
            shoppingNavigation=WebShoppingDomain.Navigation.confirm(actual.before,value.shopping,actual.action,
                    actual.run,actual.accepted,actual.dispatched,actual.stale,actual.start,actual.end);
            record("web-navigation-"+actual.run+".json",new JSONObject(shoppingNavigation.evidence()));
            pendingNavigation=null;
        }
        return shoppingNavigation!=null?value.withNavigation(shoppingNavigation):value;
    }
    boolean released(){return retired&&cleanupKnown;}
    synchronized void acceptReconciliation(Cleanup proof)throws Exception{
        need(proof!=null&&proof.known&&retired&&Boolean.TRUE.equals(proof.evidence.get("cleanup_known"))
                &&taskId.equals(proof.evidence.getString("task_id"))
                &&journal.bindingSha.equals(proof.evidence.getString("binding_sha256"))
                &&!hasUnreleased(service),"helper retirement proof does not match this original task");
        cleanupKnown=true;
    }
    void serviceRetired(){retired=true;domain=null;pendingNavigation=null;shoppingNavigation=null;dispatchSource=null;client.close();}
    Cleanup close(String reason){
        retired=true;domain=null;pendingNavigation=null;shoppingNavigation=null;dispatchSource=null;completion.clearWebDomain();
        try{
            if(!journal.attachWasPrepared()){
                journal.closeNeverAttached();cleanupKnown=true;
                return new Cleanup(true,new JSONObject().put("cleanup_known",true).put("no_attach_request_prepared",true)
                        .put("task_id",taskId).put("binding_sha256",journal.bindingSha));
            }
            WebEvidenceReceipt proof=client.closeLease(reason,SystemClock.elapsedRealtime()+10000);
            journal.closeKnown(proof);cleanupKnown=true;
            return new Cleanup(true,new JSONObject().put("cleanup_known",true).put("helper",proof.callback())
                    .put("task_id",taskId).put("binding_sha256",journal.bindingSha).put("business_verified",false));
        }catch(Exception unknown){
            try{return new Cleanup(false,new JSONObject().put("cleanup_known",false).put("task_id",taskId)
                    .put("binding_sha256",journal.bindingSha).put("error",HeptaAccessibilityService.limited(HeptaAccessibilityService.message(unknown),512))
                    .put("automatic_retry",false));}catch(Exception impossible){throw new IllegalStateException(impossible);}
        }finally{client.close();}
    }
    static Cleanup reconcile(Context context)throws Exception{
        if(!hasUnreleased(context))return new Cleanup(true,new JSONObject().put("cleanup_known",true).put("no_web_lease",true));
        WebEvidenceJournal original=WebEvidenceJournal.open(context);
        if(!original.attachWasPrepared()){original.closeNeverAttached();return new Cleanup(true,new JSONObject().put("cleanup_known",true).put("no_attach_request_prepared",true).put("task_id",original.taskId).put("binding_sha256",original.bindingSha));}
        JSONObject binding=original.binding();
        WebHelperIdentity controller=WebHelperIdentity.read(context,WebEvidenceProtocol.CONTROLLER_PACKAGE),helper=WebHelperIdentity.read(context,WebEvidenceProtocol.HELPER_PACKAGE);
        controller.requireRequest(binding.getJSONObject("controller_identity"));helper.requireRequest(binding.getJSONObject("helper_identity"));
        WebEvidenceClient client=new WebEvidenceClient(context,controller,helper,binding,new WebEvidenceClient.Guard(){
            public void requireCurrent(boolean cleanup)throws Exception{
                need(cleanup,"recovery is close-only; no old task action may resume");
                WebHelperIdentity.requirePeer(context,controller,helper);
            }
            public boolean cancelled(){return false;}
        },original);
        try{
            long deadline=SystemClock.elapsedRealtime()+10000;client.connect(deadline);
            WebEvidenceReceipt proof=client.closeLease("error",deadline);original.closeKnown(proof);
            return new Cleanup(true,new JSONObject().put("cleanup_known",true).put("helper",proof.callback())
                    .put("task_id",original.taskId).put("binding_sha256",original.bindingSha)
                    .put("automatic_resume",false).put("business_verified",false));
        }finally{client.close();}
    }
    private void record(String name,JSONObject value)throws Exception{
        need(name.matches("[A-Za-z0-9_.-]+"),"fixed evidence filename");MobiMindPrivateFiles.writeNew(new File(evidence,name),value.toString(2).getBytes(StandardCharsets.UTF_8));
    }
    private static boolean sameFrame(PhoneObservation a,PhoneObservation b){
        return a.packageName.equals(b.packageName)&&a.windowId==b.windowId&&a.rotation==b.rotation
                &&a.treeSha256.equals(b.treeSha256)&&a.state.appTreeSha256.equals(b.state.appTreeSha256)
                &&a.backgroundGeneration!=null&&a.backgroundGeneration.equals(b.backgroundGeneration)
                &&a.windowMetadata.displayId!=null&&a.windowMetadata.displayId.equals(b.windowMetadata.displayId);
    }
    private static void need(boolean condition,String reason){WebEvidenceJson.need(condition,reason);}
}

package org.trillionnium.hepta.local;

import android.content.Context;
import android.content.pm.ApplicationInfo;
import android.content.pm.PackageInfo;
import android.content.pm.PackageManager;
import android.content.pm.Signature;
import android.os.Process;
import android.system.Os;
import android.system.OsConstants;
import android.system.StructStat;
import org.json.JSONObject;
import org.trillionnium.hepta.webprotocol.WebEvidenceBinding;
import org.trillionnium.hepta.webprotocol.WebEvidenceProtocol;
import java.io.FileDescriptor;
import java.io.FileInputStream;
import java.security.MessageDigest;
import java.util.Map;
import java.util.TreeMap;

/** Actual ordinary installed package identity. Never trusts a caller-supplied UID. */
final class WebHelperIdentity {
    private static final long MAX_APK=256L*1024*1024,MAX_SET=512L*1024*1024;
    final String packageName;
    final int uid;
    final long version;
    final String signer;
    final TreeMap<String,String> paths;
    final TreeMap<String,Stamp> stamps;
    final JSONObject evidence;
    private WebHelperIdentity(String name,int uid,long version,String signer,TreeMap<String,String> paths,
            TreeMap<String,Stamp> stamps,JSONObject evidence){
        this.packageName=name;this.uid=uid;this.version=version;this.signer=signer;
        this.paths=paths;this.stamps=stamps;this.evidence=evidence;
    }
    static void requirePeer(Context context,WebHelperIdentity controller,WebHelperIdentity helper)throws Exception{
        WebEvidenceJson.need(controller.packageName.equals(WebEvidenceProtocol.CONTROLLER_PACKAGE)
                &&helper.packageName.equals(WebEvidenceProtocol.HELPER_PACKAGE)
                &&controller.uid==Process.myUid()&&controller.uid!=helper.uid,"separate current controller/helper identity required");
        controller.requireUnchanged(context);helper.requireUnchanged(context);
        PackageManager pm=context.getPackageManager();
        WebEvidenceJson.need(pm.checkSignatures(controller.uid,helper.uid)==PackageManager.SIGNATURE_MATCH,
                "controller/helper current signatures differ");
        PackageInfo installed=info(pm,helper.packageName);
        WebEvidenceJson.need(helper.version==WebEvidenceProtocol.HELPER_VERSION_CODE
                &&WebEvidenceProtocol.HELPER_VERSION_NAME.equals(installed.versionName),"current formal helper release required");
        android.content.pm.ServiceInfo service=pm.getServiceInfo(
                new android.content.ComponentName(WebEvidenceProtocol.HELPER_PACKAGE,WebEvidenceProtocol.SERVICE_CLASS),0);
        WebEvidenceJson.need(service.exported&&service.enabled&&service.applicationInfo.enabled
                &&service.applicationInfo.uid==helper.uid
                &&WebEvidenceProtocol.PERMISSION.equals(service.permission),"explicit signature evidence service required");
        android.content.pm.PermissionInfo permission=pm.getPermissionInfo(WebEvidenceProtocol.PERMISSION,0);
        WebEvidenceJson.need(WebEvidenceProtocol.HELPER_PACKAGE.equals(permission.packageName)
                &&(permission.protectionLevel&android.content.pm.PermissionInfo.PROTECTION_MASK_BASE)
                    ==android.content.pm.PermissionInfo.PROTECTION_SIGNATURE
                &&pm.checkPermission(WebEvidenceProtocol.PERMISSION,controller.packageName)==PackageManager.PERMISSION_GRANTED,
                "signature evidence permission unavailable");
    }
    static WebHelperIdentity read(Context context,String name)throws Exception{
        WebEvidenceJson.need(name.equals(WebEvidenceProtocol.CONTROLLER_PACKAGE)||name.equals(WebEvidenceProtocol.HELPER_PACKAGE),"fixed package only");
        PackageManager pm=context.getPackageManager();PackageInfo info=info(pm,name);int uid=info.applicationInfo.uid;
        WebEvidenceJson.need(uid>=10000,"ordinary application UID required");String signer=signer(info);
        WebEvidenceJson.need(WebEvidenceProtocol.SIGNER_SHA256.equals(signer),"approved signer required");
        TreeMap<String,String> paths=paths(info.applicationInfo);TreeMap<String,Stamp> stamps=new TreeMap<String,Stamp>();
        JSONObject hashes=new JSONObject();long total=0;
        for(Map.Entry<String,String> entry:paths.entrySet()){
            Stamp before=Stamp.read(entry.getValue());total+=before.size;
            WebEvidenceJson.need(before.size>0&&before.size<=MAX_APK&&total<=MAX_SET,"APK byte budget");
            hashes.put(entry.getKey(),fileSha(entry.getValue(),before));stamps.put(entry.getKey(),before);
        }
        StringBuilder set=new StringBuilder();for(String logical:paths.keySet())set.append(logical).append('\t').append(hashes.getString(logical)).append('\n');
        JSONObject evidence=new JSONObject().put("package",name).put("uid",uid).put("version_code",info.getLongVersionCode())
                .put("apk_hashes",hashes).put("apk_set_sha256",WebEvidenceJson.sha(set.toString())).put("signer_sha256",signer);
        WebHelperIdentity out=new WebHelperIdentity(name,uid,info.getLongVersionCode(),signer,paths,stamps,evidence);
        out.requireUnchanged(context);return out;
    }
    void requireRequest(JSONObject claimed)throws Exception{
        WebEvidenceJson.keys(claimed,WebEvidenceProtocol.IDENTITY_KEYS);
        WebEvidenceJson.need(WebEvidenceBinding.canonical(claimed).equals(WebEvidenceBinding.canonical(evidence)),"installed identity differs");
    }
    void requireUnchanged(Context context)throws Exception{
        PackageInfo now=info(context.getPackageManager(),packageName);
        WebEvidenceJson.need(now.applicationInfo.uid==uid&&now.getLongVersionCode()==version&&signer.equals(signer(now))
                &&paths.equals(paths(now.applicationInfo)),"installed identity changed");
        for(String key:paths.keySet())WebEvidenceJson.need(stamps.get(key).same(Stamp.read(paths.get(key))),"installed APK changed");
    }
    private static PackageInfo info(PackageManager pm,String name)throws Exception{
        return pm.getPackageInfo(name,PackageManager.GET_SIGNING_CERTIFICATES);
    }
    private static String signer(PackageInfo info)throws Exception{
        WebEvidenceJson.need(info.signingInfo!=null&&!info.signingInfo.hasMultipleSigners(),"one current signer required");
        Signature[] certificates=info.signingInfo.getApkContentsSigners();
        WebEvidenceJson.need(certificates!=null&&certificates.length==1,"one actual certificate required");return WebEvidenceJson.sha(certificates[0].toByteArray());
    }
    private static TreeMap<String,String> paths(ApplicationInfo info)throws Exception{
        TreeMap<String,String> out=new TreeMap<String,String>();WebEvidenceJson.need(info.sourceDir!=null,"base APK path missing");out.put("base",info.sourceDir);
        String[] splits=info.splitSourceDirs,names=info.splitNames;
        WebEvidenceJson.need((splits==null||splits.length==0)==(names==null||names.length==0),"split identity missing");
        if(splits!=null){WebEvidenceJson.need(names!=null&&splits.length==names.length&&splits.length<=32,"split identity count");
            for(int i=0;i<splits.length;i++){WebEvidenceJson.need(names[i]!=null&&names[i].matches("[A-Za-z0-9_.-]{1,120}")&&splits[i]!=null,"split identity invalid");
                WebEvidenceJson.need(out.put("split:"+names[i],splits[i])==null,"duplicate split identity");}}
        return out;
    }
    private static String fileSha(String path,Stamp expected)throws Exception{
        FileDescriptor fd=Os.open(path,OsConstants.O_RDONLY|OsConstants.O_CLOEXEC|OsConstants.O_NOFOLLOW,0);
        try(FileInputStream in=new FileInputStream(fd)){
            WebEvidenceJson.need(expected.same(new Stamp(Os.fstat(fd))),"opened APK differs");MessageDigest digest=MessageDigest.getInstance("SHA-256");
            byte[] buffer=new byte[65536];long bytes=0;int n;while((n=in.read(buffer))!=-1){bytes+=n;WebEvidenceJson.need(bytes<=expected.size,"APK grew");digest.update(buffer,0,n);}
            WebEvidenceJson.need(bytes==expected.size&&expected.same(new Stamp(Os.fstat(fd)))&&expected.same(Stamp.read(path)),"APK changed while hashing");
            byte[] sha=digest.digest();StringBuilder hex=new StringBuilder(64);for(byte b:sha)hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return hex.toString();
        }
    }
    private static final class Stamp {
        final long dev,ino,size,mtime,ctime;final int mode;final long links;
        Stamp(StructStat s){dev=s.st_dev;ino=s.st_ino;size=s.st_size;mtime=s.st_mtime;ctime=s.st_ctime;mode=s.st_mode;links=s.st_nlink;}
        static Stamp read(String path)throws Exception{Stamp s=new Stamp(Os.lstat(path));WebEvidenceJson.need(OsConstants.S_ISREG(s.mode)&&s.links==1,"regular immutable APK required");return s;}
        boolean same(Stamp s){return dev==s.dev&&ino==s.ino&&size==s.size&&mtime==s.mtime&&ctime==s.ctime&&mode==s.mode&&links==s.links;}
    }
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;

/**
 * Replays the owned WebView's four real native samples. This establishes a
 * stable native rectangle only; it never converts CSS geometry into a click.
 */
final class WebNativeGeometry {
    static final String SCHEMA="hepta.webview-geometry-bracket.v1";
    private static final String[] PHASES={"before_js1","after_js1","before_js2","after_js2"};
    final int displayId,windowId;
    final int[] bounds;
    final long firstSample,lastSample;
    final String fingerprint;
    private final String actualRaw;

    private WebNativeGeometry(JSONObject original,int display,int window,int[] bounds,
                              long first,long last,String stable)throws Exception{
        displayId=display;windowId=window;this.bounds=bounds.clone();
        firstSample=first;lastSample=last;fingerprint=sha(stable);actualRaw=original.toString();
    }

    /** Missing legacy geometry is not an action capability. Malformed new evidence is rejected. */
    static WebNativeGeometry read(JSONObject capture,JSONObject dom,int display,int window)throws Exception{
        if(!capture.has("capture_geometry"))return null;
        JSONObject geometry=capture.getJSONObject("capture_geometry");
        keys(geometry,"schema","samples","native_samples_equal","dom_equal_across_visual_callback",
                "ui_thread_bracket","get_scale_is_deprecated_racy_observation","css_to_screen_mapping_verified");
        need(SCHEMA.equals(string(geometry,"schema")),"native geometry schema");
        for(String key:new String[]{"native_samples_equal","dom_equal_across_visual_callback","ui_thread_bracket",
                "get_scale_is_deprecated_racy_observation"})need(Boolean.TRUE.equals(geometry.get(key)),"native geometry fact: "+key);
        need(Boolean.FALSE.equals(geometry.get("css_to_screen_mapping_verified")),"CSS mapping is not verified");
        need(display>0&&window>=0&&integer(capture,"display_id")==display
                &&integer(capture,"actual_window_id")==window,"actual geometry display/window");
        long started=integer(capture,"started_elapsed_ms"),ended=integer(capture,"ended_elapsed_ms");
        need(started>=0&&ended>=started&&ended-started<=3000,"bounded actual capture interval");
        int[] expected=rect(capture.getJSONArray("webview_bounds_screen_pixels"),true);
        JSONArray samples=geometry.getJSONArray("samples");need(samples.length()==4,"four ordered native samples");
        String firstStable=null;long first=-1,last=-1;
        for(int i=0;i<4;i++){
            JSONObject sample=samples.getJSONObject(i);keys(sample,"phase","native");
            need(PHASES[i].equals(string(sample,"phase")),"native geometry phase order");
            JSONObject nativeState=sample.getJSONObject("native");
            keys(nativeState,"sampled_elapsed_ms","display_id","actual_window_id","bounds_screen_pixels",
                    "global_visible_rect_pixels","global_visible_rect_source","scroll_pixels","padding_pixels",
                    "view_transform","webview_get_scale","scale_change_sequence","scale_changed_elapsed_ms",
                    "scale_callback_old","scale_callback_new","use_wide_viewport","load_with_overview_mode");
            long now=integer(nativeState,"sampled_elapsed_ms");
            need(now>=started&&now<=ended&&(last<0||now>=last),"native sample outside capture interval");
            if(i==0)first=now;last=now;
            need(integer(nativeState,"display_id")==display&&integer(nativeState,"actual_window_id")==window,
                    "native sample belongs to another window");
            int[] bounds=rect(nativeState.getJSONArray("bounds_screen_pixels"),true);
            need(Arrays.equals(expected,bounds),"native view rectangle changed");
            int[] visible=rect(nativeState.getJSONArray("global_visible_rect_pixels"),false);
            need("View.getGlobalVisibleRect; root-view coordinates".equals(string(nativeState,"global_visible_rect_source")),
                    "global visible rectangle provenance");
            // These coordinates have another origin. Only their dimensions are
            // compared; they are never treated as screen positions.
            need(visible[2]-visible[0]==bounds[2]-bounds[0]&&visible[3]-visible[1]==bounds[3]-bounds[1],
                    "native WebView is partly clipped");
            long[] scroll=integerArray(nativeState.getJSONArray("scroll_pixels"),2);
            long[] padding=integerArray(nativeState.getJSONArray("padding_pixels"),4);
            for(long value:padding)need(value==0,"unreviewed WebView padding");
            double[] transform=numberArray(nativeState.getJSONArray("view_transform"),5);
            need(transform[0]==1.0&&transform[1]==1.0&&transform[2]==0.0&&transform[3]==0.0&&transform[4]==0.0,
                    "unreviewed native transform");
            double scale=number(nativeState.get("webview_get_scale"));
            need(scale>0&&scale<=64,"actual native scale range");
            long sequence=integer(nativeState,"scale_change_sequence"),changed=integer(nativeState,"scale_changed_elapsed_ms");
            need(sequence>=0&&changed>=0&&changed<=now,"actual scale callback history");
            Object oldScale=nativeState.get("scale_callback_old"),newScale=nativeState.get("scale_callback_new");
            need((oldScale==JSONObject.NULL)==(newScale==JSONObject.NULL),"scale callback pair");
            if(oldScale==JSONObject.NULL)need(sequence==0&&changed==0,"missing actual scale callback values");
            else need(sequence>0&&changed>0&&number(oldScale)>0&&number(newScale)>0,"actual scale callback values");
            need(Boolean.TRUE.equals(nativeState.get("use_wide_viewport"))
                    &&Boolean.TRUE.equals(nativeState.get("load_with_overview_mode")),"actual viewport settings");
            JSONObject stable=new JSONObject();
            // A fixed key order and normalized finite numeric values allow an
            // exact cross-capture comparison without using binding's integer-only codec.
            stable.put("display",display).put("window",window).put("bounds",new JSONArray(bounds))
                    .put("visible_dimensions",new JSONArray(new int[]{visible[2]-visible[0],visible[3]-visible[1]}))
                    .put("visible_root_rectangle",new JSONArray(visible)).put("scroll",new JSONArray(scroll))
                    .put("padding",new JSONArray(padding)).put("transform",new JSONArray(transform))
                    .put("scale",scale).put("scale_sequence",sequence).put("scale_changed",changed)
                    .put("scale_old",oldScale==JSONObject.NULL?JSONObject.NULL:number(oldScale))
                    .put("scale_new",newScale==JSONObject.NULL?JSONObject.NULL:number(newScale));
            String current=stable.toString();
            if(firstStable==null)firstStable=current;else need(firstStable.equals(current),"native geometry changed across JS samples");
        }
        need(("hepta.fixed-top-document-dom.v2".equals(string(dom,"schema"))
                ||"hepta.fixed-top-document-dom.v3".equals(string(dom,"schema")))
                &&Boolean.FALSE.equals(dom.get("geometry_semantics_verified")),"actual viewport observer schema");
        JSONObject vv=dom.getJSONObject("visual_viewport");
        keys(vv,"width","height","offset_left","offset_top","page_left","page_top","scale");
        need(number(vv.get("width"))>0&&number(vv.get("height"))>0
                &&number(vv.get("scale"))>0&&number(vv.get("scale"))<=64,"actual visual viewport dimensions");
        for(String key:new String[]{"offset_left","offset_top","page_left","page_top"})number(vv.get(key));
        numberArray(dom.getJSONArray("viewport_css_pixels"),2);
        numberArray(dom.getJSONArray("layout_viewport_css_pixels"),2);
        numberArray(dom.getJSONArray("document_scroll_css_pixels"),2);
        numberArray(dom.getJSONArray("document_extent_css_pixels"),2);
        // DOM geometry is retained as an independent state guard. It is not a
        // formula for translating CSS positions or DPR into Android coordinates.
        JSONObject stable=new JSONObject().put("native",new JSONObject(firstStable))
                .put("visual_viewport",vv).put("viewport",dom.getJSONArray("viewport_css_pixels"))
                .put("layout_viewport",dom.getJSONArray("layout_viewport_css_pixels"))
                .put("document_scroll",dom.getJSONArray("document_scroll_css_pixels"))
                .put("document_extent",dom.getJSONArray("document_extent_css_pixels"));
        return new WebNativeGeometry(geometry,display,window,expected,first,last,stable.toString());
    }
    JSONObject evidence()throws Exception{
        return new JSONObject().put("schema","hepta.native-webview-geometry-replay.v1")
                .put("native_geometry_sha256",fingerprint).put("display_id",displayId).put("window_id",windowId)
                .put("native_bounds_screen_pixels",new JSONArray(bounds)).put("first_sample_elapsed_ms",firstSample)
                .put("last_sample_elapsed_ms",lastSample).put("source_geometry",new JSONObject(actualRaw))
                .put("css_to_screen_mapping_used",false).put("proves_action_or_occlusion",false);
    }
    boolean same(WebNativeGeometry other){return other!=null&&fingerprint.equals(other.fingerprint);}
    boolean contains(int left,int top,int right,int bottom){
        return left<right&&top<bottom&&bounds[0]<=left&&bounds[1]<=top&&right<=bounds[2]&&bottom<=bounds[3];
    }
    static int[] rect(JSONArray value,boolean screen)throws Exception{
        long[] raw=integerArray(value,4);int[] out=new int[4];
        for(int i=0;i<4;i++){need(raw[i]>=-32768&&raw[i]<=32768,"bounded native rectangle");out[i]=(int)raw[i];}
        need(out[0]<out[2]&&out[1]<out[3]&&(!screen||out[0]>=0&&out[1]>=0),"nonempty native rectangle");
        return out;
    }
    private static long[] integerArray(JSONArray values,int length)throws Exception{
        need(values.length()==length,"integer array shape");long[] out=new long[length];
        for(int i=0;i<length;i++){Object value=values.get(i);need(value instanceof Integer||value instanceof Long,"actual integer array value");out[i]=((Number)value).longValue();}
        return out;
    }
    private static double[] numberArray(JSONArray values,int length)throws Exception{
        need(values.length()==length,"numeric array shape");double[] out=new double[length];
        for(int i=0;i<length;i++)out[i]=number(values.get(i));return out;
    }
    private static double number(Object value){need(value instanceof Number,"actual numeric value");double n=((Number)value).doubleValue();
        need(!Double.isNaN(n)&&!Double.isInfinite(n),"finite numeric value");return n;}
    private static long integer(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof Integer||raw instanceof Long,"actual integer: "+key);return ((Number)raw).longValue();
    }
    private static String string(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof String,"actual string: "+key);return (String)raw;
    }
    private static void keys(JSONObject value,String...expected){
        Set<String> found=new HashSet<String>();Iterator<String> it=value.keys();while(it.hasNext())found.add(it.next());
        need(found.equals(new HashSet<String>(Arrays.asList(expected))),"exact geometry fields");
    }
    private static String sha(String value)throws Exception{
        byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();
    }
    private static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
}

