    }
    static WebShoppingDomain observed(String task,WebShoppingGoal goal,TaskAuthorization.Gate auth,PhoneObservation frame,
                                      WebEvidenceReceipt receipt,JSONObject immutableBinding)throws Exception{
        String binding=common(task,goal,auth,frame,receipt,immutableBinding);
        need("captured".equals(receipt.status),"actual captured page required");
        JSONObject dom=receipt.dom(),capture=receipt.capture();WebSitePolicy policy=WebSitePolicy.forShopping(goal);
        MiPublicProductPage page=MiPublicProductPage.read(goal,policy,receipt.url,dom);
        WebNativeGeometry geometry=WebNativeGeometry.read(capture,dom,receipt.displayId,receipt.windowId);
        Map<String,MiPublicProductPage.Link> targets=new LinkedHashMap<String,MiPublicProductPage.Link>();
        List<Map<String,Object>> capabilities=new ArrayList<Map<String,Object>>();
        Map<String,Object> proof=base(task,goal,auth,frame,receipt,binding);
        proof.put("page",page.evidence());proof.put("site_policy",jsonMap(policy.evidence()));
        proof.put("site_policy_sha256",policy.sha256);proof.put("native_geometry",geometry==null?null:geometry.evidence());
        if(geometry!=null&&!page.modalPresent&&page.productLinks.size()==1
                &&"official_public_search".equals(page.phase)){
            MiPublicProductPage.Link link=page.productLinks.get(0);
            if(page.uniqueId(link.id)){
                PhoneObservation.Node node=uniqueClick(frame,geometry,link);
                if(node!=null){
                    targets.put(node.id,link);Map<String,Object> cap=nodeEvidence(node);
                    cap.put("purpose","open_observed_official_product_detail");cap.put("observed_link",link.evidence());
                    cap.put("target_source","same_frame_native_accessibility_node_id");cap.put("css_rect_used_as_target",false);
                    capabilities.add(cap);
                }
            }
        }
        boolean localPrice=false;
        Map<String,Object> visible=new LinkedHashMap<String,Object>();
        if(geometry!=null&&!page.modalPresent&&page.detail!=null&&page.detail.exactPublicPrice
                &&!goal.singleUnitRequested&&!goal.specificationsRequested){
            MiPublicProductPage.Detail detail=page.detail;
            PhoneObservation.Node model=uniqueReadable(frame,geometry,detail.modelLabel);
            PhoneObservation.Node amount=uniqueReadable(frame,geometry,detail.priceRaw);
            PhoneObservation.Node currency=uniqueReadable(frame,geometry,detail.currencyRaw);
            if(model!=null&&amount!=null&&currency!=null&&model!=amount&&model!=currency&&amount!=currency){
                localPrice=true;visible.put("model",nodeEvidence(model));visible.put("price",nodeEvidence(amount));
                visible.put("currency",nodeEvidence(currency));
            }
        }
        proof.put("phase",page.phase);proof.put("native_ax_capabilities",capabilities);
        proof.put("allowed_click_ids",new ArrayList<String>(targets.keySet()));
        proof.put("actual_product_native_readback",visible);proof.put("same_frame_public_price_observed",localPrice);
        proof.put("model_navigation_confirmed",false);proof.put("model_navigation",null);
        proof.put("result_ready_for_completion_gate",false);
        proof.put("missing",new ArrayList<String>(page.missing));
        proof.put("next_goal",!targets.isEmpty()?"打开同帧实际 AX3000T 官方商品链接；不要点击购买、登录、领券或购物车。":
                localPrice?"已观察到商品公开价；仍须同任务原生模型导航因果链及最终清理门。":
                "当前页面缺少可验证的公开商品控件或价格；只能等待或报告未完成，不能猜测SKU、价格、币种。");
        JSONObject semantic=new JSONObject().put("native_url",receipt.url).put("instance",receipt.instance)
                .put("epoch",receipt.epoch).put("policy_sha256",policy.sha256)
                .put("native_geometry_sha256",geometry==null?JSONObject.NULL:geometry.fingerprint)
                .put("capabilities",new org.json.JSONArray(capabilities)).put("page",new JSONObject(page.evidence()));
        return new WebShoppingDomain(task,goal,auth,frame,receipt,binding,page.phase,WebEvidenceJson.sha(semantic.toString()),
                targets,page,localPrice,null,proof);
    }
    static WebShoppingDomain waiting(String task,WebShoppingGoal goal,TaskAuthorization.Gate auth,PhoneObservation frame,
                                    WebEvidenceReceipt receipt,JSONObject immutableBinding)throws Exception{
        String binding=common(task,goal,auth,frame,receipt,immutableBinding);
        need(("unavailable".equals(receipt.status)||"state_changed".equals(receipt.status))&&!receipt.cleanupKnown,
                "only authenticated metadata-only capture wait");
        Map<String,Object> proof=base(task,goal,auth,frame,receipt,binding);proof.put("phase","official_page_capture_pending");
        proof.put("capture_callback",jsonMap(receipt.callback()));proof.put("allowed_click_ids",Collections.emptyList());
        proof.put("native_ax_capabilities",Collections.emptyList());proof.put("same_frame_public_price_observed",false);
        proof.put("model_navigation_confirmed",false);proof.put("result_ready_for_completion_gate",false);
        proof.put("next_goal","网页原始证据尚未稳定；只能等待或报告未完成。");
        return new WebShoppingDomain(task,goal,auth,frame,receipt,binding,"official_page_capture_pending",
                WebEvidenceJson.sha(receipt.callback().toString()+"\n"+frame.id),
                Collections.<String,MiPublicProductPage.Link>emptyMap(),null,false,null,proof);
    }
    private static String common(String task,WebShoppingGoal goal,TaskAuthorization.Gate auth,PhoneObservation frame,
                               WebEvidenceReceipt receipt,JSONObject immutableBinding)throws Exception{
        need(goal!=null&&auth!=null&&receipt!=null&&task.equals(auth.taskId)&&goal.ownerSha256.equals(auth.authorization.instructionSha256)
                &&WebShoppingGoal.TOOL_CEILING.containsAll(auth.authorization.allowedTools),"same original bounded shopping authorization");
        need(WebEvidenceProtocol.HELPER_VERSION_CODE==5
                &&"hepta.web-helper.binding.v3".equals(WebEvidenceProtocol.BINDING_SCHEMA)
                &&"org.trillionnium.hepta.webhelper.IWebEvidence.v3".equals(WebEvidenceProtocol.DESCRIPTOR),
                "shopping requires explicit code5/v3 peer; signed code4 cannot be repurposed");
        WebSitePolicy policy=WebSitePolicy.forShopping(goal);
        need(immutableBinding!=null&&WebEvidenceProtocol.BINDING_SCHEMA.equals(immutableBinding.get("schema"))
                &&task.equals(immutableBinding.get("task_id"))&&goal.owner.equals(immutableBinding.get("owner"))
                &&goal.ownerSha256.equals(immutableBinding.get("owner_sha256"))&&goal.contractSha256.equals(immutableBinding.get("contract_sha256"))
                &&WebShoppingGoal.KIND.equals(immutableBinding.get("goal_kind"))
                &&policy.id.equals(immutableBinding.get("site_policy_id"))&&policy.sha256.equals(immutableBinding.get("site_policy_sha256"))
                &&policy.initialUrl.equals(immutableBinding.get("initial_url"))
                &&auth.authorization.sha256.equals(immutableBinding.getJSONObject("authorization").get("authorization_sha256"))
                &&WebEvidenceJson.number(immutableBinding.getJSONObject("helper_identity"),"version_code")==5,
                "exact per-lease shopping contract/site/authority binding required");
        String binding=WebEvidenceBinding.sha256(immutableBinding);
        need(frame!=null&&!frame.nodesTruncated&&WebEvidenceProtocol.HELPER_PACKAGE.equals(frame.packageName)
                &&frame.windowMetadata!=null&&"observed".equals(frame.windowMetadata.status)
                &&Integer.valueOf(1).equals(frame.windowMetadata.type)&&frame.windowMetadata.displayId!=null
                &&frame.windowMetadata.displayId==receipt.displayId&&frame.windowId==receipt.windowId
                &&receipt.displayId>0&&frame.backgroundGeneration!=null&&binding.equals(receipt.bindingSha)
                &&WebEvidenceJson.number(immutableBinding.getJSONObject("background"),"display_id")==receipt.displayId
                &&frame.backgroundGeneration.equals(immutableBinding.getJSONObject("background").get("generation")),
                "same current owned AX/DOM application window required");
        return binding;
    }
    private static Map<String,Object> base(String task,WebShoppingGoal goal,TaskAuthorization.Gate auth,PhoneObservation frame,
                                           WebEvidenceReceipt receipt,String binding){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema",SCHEMA);out.put("task_id",task);
        out.put("owner_sha256",goal.ownerSha256);out.put("contract_sha256",goal.contractSha256);out.put("authorization_sha256",auth.authorization.sha256);
        out.put("observation_id",frame.id);out.put("observation_state_sha256",frame.treeSha256);out.put("app_tree_sha256",frame.state.appTreeSha256);
        out.put("binding_sha256",binding);out.put("webview_instance",receipt.instance);out.put("navigation_epoch",receipt.epoch);
        out.put("display_id",receipt.displayId);out.put("window_id",receipt.windowId);out.put("background_generation",frame.backgroundGeneration);
        out.put("current_native_url",receipt.url);out.put("dom_sha256",receipt.domSha);out.put("business_verified",false);
        out.put("grants_tool_authority",false);out.put("bootstrap_search_is_model_query",false);
        out.put("css_to_screen_mapping_used",false);out.put("dom_layout_visibility_is_screen_proof",false);
        out.put("final_native_and_cleanup_gates_verified",false);return out;
    }
    WebShoppingDomain withNavigation(Navigation proof){
        need(proof!=null&&proof.matches(this),"navigation belongs to another task/product/page");
        return new WebShoppingDomain(this,proof);
    }
    boolean resultReady(){return localPriceVerified&&navigation!=null&&navigation.matches(this);}
    Map<String,Object> resultRecord(){
        need(resultReady()&&page!=null&&page.detail!=null,"actual same-product result and navigation missing");
        Map<String,Object> out=new LinkedHashMap<String,Object>(page.detail.evidence());
        out.put("committed_url",url);out.put("task_id",taskId);out.put("owner_sha256",ownerSha);out.put("contract_sha256",contractSha);
        out.put("observation_id",observationId);out.put("observation_state_sha256",stateSha);out.put("binding_sha256",bindingSha);
        out.put("webview_instance",instance);out.put("navigation_epoch",epoch);out.put("display_id",displayId);out.put("window_id",windowId);
        out.put("model_navigation",navigation.evidence());out.put("same_frame_native_labels_verified",true);
        out.put("exact_configuration_verified",false);out.put("price_scope","displayed_public_product_page_price");
        out.put("business_verified",false);out.put("final_native_and_cleanup_gates_verified",false);return out;
    }
    Map<String,Object> evidence(){return new LinkedHashMap<String,Object>(proof);}
    Set<String> clicks(Set<String> original){Set<String> out=new HashSet<String>(original);out.retainAll(clickIds);return out;}
    Set<String> edits(Set<String> original){return Collections.emptySet();}
    Set<String> openPackages(Set<String> original){return Collections.emptySet();}
    <T> Map<String,T> noNodeActions(Map<String,T> original){return Collections.emptyMap();}
    Set<String> toolMask(Set<String> original){
        Set<String> out=new HashSet<String>(Arrays.asList("wait","done"));if(!clickIds.isEmpty())out.add("click");
        if(original!=null)out.retainAll(original);return out;
    }
    void requireCurrent(ActionDecision action){
        need(action!=null&&observationId.equals(action.observationId)&&WebEvidenceProtocol.HELPER_PACKAGE.equals(action.packageName),
                "shopping action belongs to another current frame");
        if("wait".equals(action.action))return;
        if("done".equals(action.action)){need(!"success".equals(action.status)||resultReady(),"actual product result not yet independently ready");return;}
        if("click".equals(action.action)){need(action.nodeId!=null&&clickIds.contains(action.nodeId),"only current exact official product link is allowed");return;}
        throw new IllegalArgumentException("该商品页面没有已证明的只读操作；禁止购物、输入、提交或跨站操作");
    }
    static final class Navigation {
        private final String task,owner,contract,authorization,binding,generation,instance,url,run,beforeObservation,afterObservation;
        private final int display,window;private final long targetEpoch,dispatchBefore,dispatchAfter;
        private final Map<String,Object> evidence;
        private Navigation(WebShoppingDomain before,WebShoppingDomain after,String modelRun,long start,long end,ActionDecision action){
            task=before.taskId;owner=before.ownerSha;contract=before.contractSha;authorization=before.authorizationSha;
            binding=before.bindingSha;generation=before.generation;instance=before.instance;url=after.url;
            display=before.displayId;window=before.windowId;targetEpoch=after.epoch;run=modelRun;
            beforeObservation=before.observationId;afterObservation=after.observationId;dispatchBefore=start;dispatchAfter=end;
            Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema","hepta.mi-model-navigation.v1");
            out.put("task_id",task);out.put("owner_sha256",owner);out.put("contract_sha256",contract);out.put("authorization_sha256",authorization);
            out.put("binding_sha256",binding);out.put("background_generation",generation);out.put("webview_instance",instance);
            out.put("display_id",display);out.put("window_id",window);out.put("model_run_id",run);out.put("action","click");out.put("node_id",action.nodeId);
            out.put("before_observation_id",beforeObservation);out.put("after_observation_id",afterObservation);
            out.put("source_url",before.url);out.put("target_url",url);out.put("source_epoch",before.epoch);out.put("target_epoch",targetEpoch);
            out.put("dispatch_before_elapsed_ms",start);out.put("dispatch_after_elapsed_ms",end);
            out.put("actual_source_link",before.links.get(action.nodeId).evidence());out.put("accepted",true);out.put("dispatched",true);out.put("stale",false);
            out.put("model_issued",true);out.put("business_verified",false);evidence=Collections.unmodifiableMap(out);
        }
        /**
         * Called only from the real controller's accepted native-model action +
         * actual executor Outcome. The clocks bracket that original dispatch.
         * Planned/unknown/stale clicks and operator navigation cannot mint this object.
         */
        static Navigation confirm(WebShoppingDomain before,WebShoppingDomain after,ActionDecision action,String nativeModelRunId,
                                  boolean accepted,boolean dispatched,boolean stale,long dispatchBefore,long dispatchAfter){
            need(before!=null&&after!=null&&action!=null&&accepted&&dispatched&&!stale
                    &&nativeModelRunId!=null&&nativeModelRunId.matches("[0-9a-f]{32}"),"actual accepted model dispatch required");
            before.requireCurrent(action);need("click".equals(action.action)&&before.links.containsKey(action.nodeId),"real product link click required");
            need("official_public_search".equals(before.phase)&&"official_product_detail".equals(after.phase)
                    &&before.taskId.equals(after.taskId)&&before.ownerSha.equals(after.ownerSha)&&before.contractSha.equals(after.contractSha)
                    &&before.authorizationSha.equals(after.authorizationSha)&&before.bindingSha.equals(after.bindingSha)
                    &&before.generation.equals(after.generation)&&before.instance.equals(after.instance)
                    &&before.displayId==after.displayId&&before.windowId==after.windowId
                    &&before.links.get(action.nodeId).hrefResolved.equals(after.url)&&after.epoch>before.epoch,
                    "actual same-lease detail navigation does not match the observed source link");
            need(before.captureEnded>=0&&before.captureEnded<=dispatchBefore&&dispatchBefore<=dispatchAfter
                    &&dispatchAfter<=after.captureStarted,"actual monotonic dispatch/capture order required");
            return new Navigation(before,after,nativeModelRunId,dispatchBefore,dispatchAfter,action);
        }
        boolean matches(WebShoppingDomain now){
            return now!=null&&task.equals(now.taskId)&&owner.equals(now.ownerSha)&&contract.equals(now.contractSha)
                    &&authorization.equals(now.authorizationSha)&&binding.equals(now.bindingSha)&&generation.equals(now.generation)
                    &&instance.equals(now.instance)&&url.equals(now.url)&&display==now.displayId&&window==now.windowId&&now.epoch>=targetEpoch;
        }
        Map<String,Object> evidence(){return new LinkedHashMap<String,Object>(evidence);}
    }
    private static PhoneObservation.Node uniqueClick(PhoneObservation frame,WebNativeGeometry geometry,MiPublicProductPage.Link link)throws Exception{
        List<PhoneObservation.Node> matches=new ArrayList<PhoneObservation.Node>();
        for(PhoneObservation.Node node:frame.nodes)if(link.id.equals(node.viewId))matches.add(node);
        if(matches.size()!=1)return null;PhoneObservation.Node node=matches.get(0);
        if(!nativeVisible(frame,geometry,node)||!node.clickable||node.editable||node.password||node.scrollable)return null;
        String own=node.text.isEmpty()?node.description:node.text;
        if(!own.isEmpty())return link.label.equals(own)?node:null;
        ObservedChildText.Result child=node.childText;
        if(!"derived".equals(child.status)||child.truncated||!child.sourcesComplete||child.sources.isEmpty()
                ||!child.rootSignature.matches("[0-9a-f]{64}")||!child.bind(child.rootSignature).equals(node.observedAppTreeSignature))return null;
        Set<String> hashes=new HashSet<String>();for(String text:link.visibleTexts)hashes.add(WebEvidenceJson.sha(text));
        boolean model=false;for(ObservedChildText.Source source:child.sources){
            if(!source.descendantPath.matches("[0-9]+(?:/[0-9]+){0,3}")
                    ||!("text".equals(source.property)||"description".equals(source.property))
                    ||source.nodeSignature==null||!source.nodeSignature.matches("[0-9a-f]{64}")||!hashes.contains(source.textSha256))return null;
            if(WebEvidenceJson.sha(link.label).equals(source.textSha256))model=true;
        }
        return model?node:null;
    }
    private static PhoneObservation.Node uniqueReadable(PhoneObservation frame,WebNativeGeometry geometry,String label){
        List<PhoneObservation.Node> matches=new ArrayList<PhoneObservation.Node>();
        for(PhoneObservation.Node node:frame.nodes)if(label.equals(node.text.isEmpty()?node.description:node.text))matches.add(node);
        if(matches.size()!=1)return null;PhoneObservation.Node node=matches.get(0);
        return nativeVisible(frame,geometry,node)&&!node.password&&!node.editable?node:null;
    }
    private static boolean nativeVisible(PhoneObservation frame,WebNativeGeometry geometry,PhoneObservation.Node node){
        return WebEvidenceProtocol.HELPER_PACKAGE.equals(node.packageName)&&node.enabled
                &&node.observedAppTreeSignature!=null&&node.observedAppTreeSignature.matches("[0-9a-f]{64}")
                &&geometry.contains(node.bounds.left,node.bounds.top,node.bounds.right,node.bounds.bottom)
                &&inside(frame.windowMetadata.rootBounds(),node)&&inside(frame.windowMetadata.windowBounds(),node)
                &&node.bounds.left>=0&&node.bounds.top>=0&&node.bounds.right<=frame.width&&node.bounds.bottom<=frame.height;
    }
    private static boolean inside(int[] r,PhoneObservation.Node node){
        return r!=null&&r.length==4&&r[0]<=node.bounds.left&&r[1]<=node.bounds.top&&node.bounds.right<=r[2]&&node.bounds.bottom<=r[3];
    }
    private static Map<String,Object> nodeEvidence(PhoneObservation.Node node){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("node_id",node.id);out.put("native_view_id",node.viewId);
        out.put("native_class",node.className);out.put("native_label",node.label());out.put("node_app_tree_sha256",node.observedAppTreeSignature);
        out.put("native_bounds",Arrays.asList(node.bounds.left,node.bounds.top,node.bounds.right,node.bounds.bottom));return out;
    }
    private static Map<String,Object> jsonMap(JSONObject value)throws Exception{
        Map<String,Object> out=new LinkedHashMap<String,Object>();java.util.Iterator<String> keys=value.keys();
        while(keys.hasNext()){String key=keys.next();out.put(key,jsonValue(value.get(key),0));}return out;
    }
    private static Object jsonValue(Object value,int depth)throws Exception{
        need(depth<=32,"bounded JSON evidence nesting");
        if(value==JSONObject.NULL)return null;
        if(value instanceof JSONObject){
            Map<String,Object> out=new LinkedHashMap<String,Object>();java.util.Iterator<String> keys=((JSONObject)value).keys();
            while(keys.hasNext()){String key=keys.next();out.put(key,jsonValue(((JSONObject)value).get(key),depth+1));}return out;
        }
        if(value instanceof org.json.JSONArray){
            List<Object> out=new ArrayList<Object>();org.json.JSONArray a=(org.json.JSONArray)value;
            for(int i=0;i<a.length();i++)out.add(jsonValue(a.get(i),depth+1));return out;
        }
        need(value instanceof String||value instanceof Boolean||value instanceof Number,"JSON scalar evidence required");return value;
    }
    private static void need(boolean ok,String message){if(!ok)throw new IllegalArgumentException(message);}
}

package org.trillionnium.hepta.local;

import org.json.JSONObject;
import org.trillionnium.hepta.webprotocol.WebEvidenceBinding;
import org.trillionnium.hepta.webprotocol.WebEvidenceProtocol;
import org.trillionnium.hepta.webprotocol.WebTaskPurpose;
import java.util.Collections;
import java.util.Map;
import java.util.Set;

/** One of two actual page providers, with one immutable OWNER/site/lease binding. No dispatch API. */
final class WebTaskDomain {
    final String taskId,ownerSha,authorizationSha,observationId,stateSha,generation,instance,url,phase,pageKey;
    final int displayId,windowId;
    final long epoch;
    final Set<String> clickIds;
    final Map<String,String> editValues;
    final WebFlightDomain flight;
    final WebShoppingDomain shopping;
    private WebTaskDomain(WebFlightDomain value){
        flight=value;shopping=null;taskId=value.taskId;ownerSha=value.ownerSha;authorizationSha=value.authorizationSha;
        observationId=value.observationId;stateSha=value.stateSha;generation=value.generation;instance=value.instance;
        url=value.url;phase=value.phase;pageKey=value.pageKey;displayId=value.displayId;windowId=value.windowId;epoch=value.epoch;
        clickIds=value.clickIds;editValues=value.editValues;
    }
    private WebTaskDomain(WebShoppingDomain value){
        flight=null;shopping=value;taskId=value.taskId;ownerSha=value.ownerSha;authorizationSha=value.authorizationSha;
        observationId=value.observationId;stateSha=value.stateSha;generation=value.generation;instance=value.instance;
        url=value.url;phase=value.phase;pageKey=value.pageKey;displayId=value.displayId;windowId=value.windowId;epoch=value.epoch;
        clickIds=value.clickIds;editValues=Collections.emptyMap();
    }
    static WebTaskDomain observed(String task,WebTaskPurpose purpose,TaskAuthorization.Gate auth,
            PhoneObservation frame,WebEvidenceReceipt receipt,JSONObject binding)throws Exception{
        String sha=requireBound(task,purpose,auth,frame,receipt,binding);
        return purpose.flight!=null?new WebTaskDomain(WebFlightDomain.observed(task,purpose.flight,auth,frame,receipt,sha)):
                new WebTaskDomain(WebShoppingDomain.observed(task,purpose.shopping,auth,frame,receipt,binding));
    }
    static WebTaskDomain waiting(String task,WebTaskPurpose purpose,TaskAuthorization.Gate auth,
            PhoneObservation frame,WebEvidenceReceipt receipt,JSONObject binding)throws Exception{
        String sha=requireBound(task,purpose,auth,frame,receipt,binding);
        return purpose.flight!=null?new WebTaskDomain(WebFlightDomain.waiting(task,purpose.flight,auth,frame,receipt,sha)):
                new WebTaskDomain(WebShoppingDomain.waiting(task,purpose.shopping,auth,frame,receipt,binding));
    }
    private static String requireBound(String task,WebTaskPurpose purpose,TaskAuthorization.Gate auth,
            PhoneObservation frame,WebEvidenceReceipt receipt,JSONObject binding)throws Exception{
        WebTaskPurpose derived=WebTaskPurpose.requireBinding(binding);
        need(purpose!=null&&auth!=null&&frame!=null&&receipt!=null&&task.equals(auth.taskId)
                &&task.equals(binding.get("task_id"))&&purpose.owner.equals(derived.owner)
                &&purpose.contractSha256.equals(derived.contractSha256)&&purpose.kind.equals(derived.kind)
                &&purpose.sitePolicySha256.equals(derived.sitePolicySha256)
                &&purpose.ownerSha256.equals(auth.authorization.instructionSha256)
                &&WebEvidenceBinding.canonical(new JSONObject(auth.authorization.evidence())).equals(
                        WebEvidenceBinding.canonical(binding.getJSONObject("authorization"))),
                "same original OWNER, actual authority and compiled site purpose required");
        need(WebEvidenceProtocol.HELPER_VERSION_CODE==5&&"hepta.web-helper.binding.v3".equals(binding.get("schema"))
                &&WebEvidenceJson.number(binding.getJSONObject("helper_identity"),"version_code")==5,
                "current code5/v3 helper binding required");
        JSONObject bg=binding.getJSONObject("background");
        need(bg.getJSONArray("selected_packages").length()==1
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(bg.getJSONArray("selected_packages").get(0))
                &&frame.backgroundGeneration!=null&&frame.backgroundGeneration.equals(bg.get("generation"))
                &&receipt.displayId>0&&WebEvidenceJson.number(bg,"display_id")==receipt.displayId,
                "same explicit single-helper background lease required");
        String sha=WebEvidenceBinding.sha256(binding);
        need(sha.equals(receipt.bindingSha),"actual bound helper reply required");return sha;
    }
    WebTaskDomain withNavigation(WebShoppingDomain.Navigation navigation){
        need(shopping!=null&&navigation!=null&&navigation.matches(shopping),"same task product navigation required");
        return new WebTaskDomain(shopping.withNavigation(navigation));
    }
    WebTaskDomain withFlightProgress(WebFlightProgress progress)throws Exception{
        need(flight!=null&&progress!=null&&progress.matches(flight),"same task flight progression required");
        return new WebTaskDomain(flight.withProgress(progress));
    }
    boolean queryDispatched(){return flight!=null&&flight.queryDispatched();}
    boolean resultReady(){return shopping!=null&&shopping.resultReady();}
    Map<String,Object> resultRecord(){
        need(resultReady(),"actual public result and model navigation are missing");return shopping.resultRecord();
    }
    Map<String,Object> evidence(){return flight!=null?flight.evidence():shopping.evidence();}
    Set<String> clicks(Set<String> original){return flight!=null?flight.clicks(original):shopping.clicks(original);}
    Set<String> edits(Set<String> original){return flight!=null?flight.edits(original):shopping.edits(original);}
    Set<String> openPackages(Set<String> original){return flight!=null?flight.openPackages(original):shopping.openPackages(original);}
    <T> Map<String,T> noNodeActions(Map<String,T> original){return flight!=null?flight.noNodeActions(original):shopping.noNodeActions(original);}
    Set<String> toolMask(Set<String> original){return flight!=null?flight.toolMask(original):shopping.toolMask(original);}
    void requireCurrent(ActionDecision action){if(flight!=null)flight.requireCurrent(action);else shopping.requireCurrent(action);}
    private static void need(boolean yes,String reason){WebEvidenceJson.need(yes,reason);}
}

package org.trillionnium.hepta.local.web;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.DateTimeException;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Isolated candidate. A complete literal read-only flight goal, not tool authority.
 * The real phone TaskAuthorization must independently compile the identical OWNER.
 * This class neither opens a URL nor treats a query form as a flight result.
 */
public final class WebFlightGoal {
    public static final String SCHEMA = "hepta.web-flight-owner.csair.v1";
    public static final String NATURAL_SCHEMA = "hepta.web-flight-owner.csair.v2";
    public static final String NATURAL_RECOGNITION = "natural_explicit_date_single_adult_flight_query.v1";
    public static final String TAIL = "请核对实际出发日期、出发和到达机场、航班号、起降时间、公开显示的价格与币种，并注明价格包含或未注明的税费及条件。"
            + "只允许click、type、submit、scroll、back、wait、done。"
            + "输入和提交仅用于公开的城市、日期、人数及航班查询；不要登录、注册、同意授权、加购、预订、下单、支付或修改账号和权限。"
            + "遇到这些要求、访问阻断或资料不完整就停止并报告未完成。这是测试路线，不代表用户行程。";
    public static final String BACKGROUND_TAIL = TAIL.replace("只允许click、", "只允许open、click、");
    private static final Pattern OWNER = Pattern.compile(
            "网页查询测试：在南航官方网站查询([0-9]{4})年([0-9]{1,2})月([0-9]{1,2})日"
            + "([\\p{IsHan}]{2,12})到([\\p{IsHan}]{2,12})的单程航班，1名成人。" + Pattern.quote(TAIL));
    private static final Pattern BACKGROUND_OWNER = Pattern.compile(
            "网页查询测试：在南航官方网站查询([0-9]{4})年([0-9]{1,2})月([0-9]{1,2})日"
            + "([\\p{IsHan}]{2,12})到([\\p{IsHan}]{2,12})的单程航班，1名成人。" + Pattern.quote(BACKGROUND_TAIL));
    private static final String NATURAL_PREFIX = "(?:请)?(?:帮我)?(?:查一下|查询|查查)"
            + "(?:(?:南航|中国南方航空)(?:官网|官方网站)(?:上|的)?)?";
    private static final String NATURAL_ROUTE = "(?:从)?([\\p{IsHan}]{2,12}?)到([\\p{IsHan}]{2,12}?)"
            + "(?:的)?单程(?:机票|航班)[，,](?:1|一)(?:名|位)成人[。]?";
    private static final Pattern NATURAL_DATE = Pattern.compile(NATURAL_PREFIX
            + "([0-9]{4})年([0-9]{1,2})月([0-9]{1,2})日" + NATURAL_ROUTE);
    private static final Pattern NATURAL_ISO_DATE = Pattern.compile(NATURAL_PREFIX
            + "([0-9]{4})-([0-9]{2})-([0-9]{2})" + NATURAL_ROUTE);
    /** Recognition is not a grant; TaskAuthorization still compiles the original OWNER. */
    public final boolean naturalReadOnlyIntent;
    public final String contractSchema,recognition,providerSelection;
    /** Explicit OWNER token, not a grant and not proof that a background lease exists. */
    public final boolean ownerContainsOpen;
    public final String immutableOwner, ownerSha256, contractSha256, fromCity, toCity;
    public final LocalDate departureDate;
    public final int adults = 1, children = 0, infants = 0;
    public final int dateStartUtf16, dateEndUtf16, fromStartUtf16, fromEndUtf16, toStartUtf16, toEndUtf16;
    private WebFlightGoal(String owner, Matcher match, LocalDate date, boolean open) {
        this(owner,match,date,open,false,1);
    }
    private WebFlightGoal(String owner, Matcher match, LocalDate date, boolean open,boolean natural,int dateSuffix) {
        naturalReadOnlyIntent=natural;contractSchema=natural?NATURAL_SCHEMA:SCHEMA;
        recognition=natural?NATURAL_RECOGNITION:"literal_read_only_flight_test.v1";
        providerSelection=natural&&!owner.substring(0,match.start(1)).contains("南航")
                &&!owner.substring(0,match.start(1)).contains("中国南方航空")
                ?"compiled_official_csair_provider":"explicit_official_csair_owner";
        ownerContainsOpen = open;
        immutableOwner = owner;
        ownerSha256 = hash(owner);
        departureDate = date;
        fromCity = match.group(4); toCity = match.group(5);
        dateStartUtf16 = match.start(1); dateEndUtf16 = match.end(3) + dateSuffix;
        fromStartUtf16 = match.start(4); fromEndUtf16 = match.end(4);
        toStartUtf16 = match.start(5); toEndUtf16 = match.end(5);
        contractSha256 = hash(contractSchema + "\n" + ownerSha256 + "\n" + date.toString()
                + "\n" + fromCity + "\n" + toCity + "\n1\n0\n0\none_way");
    }
    /** Exact consumption only. Whitespace/suffixes, added goals or unknown syntax are unsupported. */
    public static WebFlightGoal parse(String owner) {
        if (owner == null || owner.getBytes(StandardCharsets.UTF_8).length > 1600) return null;
        Matcher match = OWNER.matcher(owner);
        boolean open = false;
        if (!match.matches()) {
            match = BACKGROUND_OWNER.matcher(owner);
            if (!match.matches()) return parseNatural(owner);
            open = true;
        }
        if (match.group(4).equals(match.group(5))) return null;
        try {
            LocalDate date = LocalDate.of(Integer.parseInt(match.group(1)),
                    Integer.parseInt(match.group(2)), Integer.parseInt(match.group(3)));
            return new WebFlightGoal(owner, match, date, open);
        } catch (DateTimeException | NumberFormatException invalid) {
            return null;
        }
    }
    private static WebFlightGoal parseNatural(String owner) {
        Matcher match=NATURAL_DATE.matcher(owner);int suffix=1;
        if(!match.matches()){match=NATURAL_ISO_DATE.matcher(owner);suffix=0;if(!match.matches())return null;}
        if(!singleCity(match.group(4))||!singleCity(match.group(5))||match.group(4).equals(match.group(5)))return null;
        try{
            LocalDate date=LocalDate.of(Integer.parseInt(match.group(1)),
                    Integer.parseInt(match.group(2)),Integer.parseInt(match.group(3)));
            return new WebFlightGoal(owner,match,date,false,true,suffix);
        }catch(DateTimeException|NumberFormatException invalid){return null;}
    }
    private static boolean singleCity(String city){
        return city.matches("[\\p{IsHan}]{2,12}")
                &&!city.matches(".*(?:或者|以及|然后|打开|查询|搜索|预订|下单|支付|删除|提醒|闹钟|成人|儿童|婴儿).*");
    }
    /** A recognized public-query purpose permits considering the compiled entry;
     * the real OWNER tool mask and selected background helper must also allow it.
     * No expanded or generated instruction is ever substituted for immutableOwner. */
    public boolean allowsInitialOfficialPage(){return ownerContainsOpen||naturalReadOnlyIntent;}
    /** Maximum purpose-compatible tools, never a grant. Intersect this with the
     * authorization compiled from the identical original OWNER and actual lease. */
    public Set<String> toolCeiling(){
        Set<String> ceiling=new TreeSet<String>(Arrays.asList("open","click","type","submit","scroll","back","wait","done"));
        if(!allowsInitialOfficialPage())ceiling.remove("open");
        return Collections.unmodifiableSet(ceiling);
    }
    /** Clock is supplied from the real task boundary, never inferred from page text. */
    public boolean departureNotBefore(LocalDate taskLocalDate) {
        return taskLocalDate != null && !departureDate.isBefore(taskLocalDate);
    }
    public Map<String,Object> evidence() {
        Map<String,Object> out = new LinkedHashMap<String,Object>();
        out.put("schema", contractSchema); out.put("owner_sha256", ownerSha256);
        out.put("contract_sha256", contractSha256); out.put("departure_date", departureDate.toString());
        out.put("from_city", fromCity); out.put("to_city", toCity); out.put("trip_type", "one_way");
        out.put("adults", adults); out.put("children", children); out.put("infants", infants);
        out.put("date_start_utf16", dateStartUtf16); out.put("date_end_utf16", dateEndUtf16);
        out.put("from_start_utf16", fromStartUtf16); out.put("from_end_utf16", fromEndUtf16);
        out.put("to_start_utf16", toStartUtf16); out.put("to_end_utf16", toEndUtf16);
        out.put("source", "complete_immutable_owner"); out.put("grants_tool_authority", false);
        out.put("airport_choice_inferred", false); out.put("query_executed", false);
        if(naturalReadOnlyIntent){
            out.put("recognition",recognition);out.put("provider_selection",providerSelection);
            out.put("owner_rewritten",false);out.put("year_explicit_in_owner",true);
            out.put("owner_contains_literal_open",ownerContainsOpen);out.put("initial_official_page_required",true);
        }
        return Collections.unmodifiableMap(out);
    }
    static String hash(String value) {
        try {
            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            char[] hex = "0123456789abcdef".toCharArray(); StringBuilder out = new StringBuilder(64);
            for (byte b : bytes) out.append(hex[(b >>> 4) & 15]).append(hex[b & 15]);
            return out.toString();
        } catch (Exception impossible) { throw new IllegalStateException(impossible); }
    }
}

package org.trillionnium.hepta.local.web;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure-Java bounded original-user intent for one official public product lookup.
 * No JSON, Android or Binder dependency is introduced into TaskAuthorization.
 * Recognition derives an immutable data contract, never rewrites OWNER and never
 * grants a tool. Original authority and current single-helper selection are
 * separate, mandatory controller/helper gates.
 */
public final class WebShoppingGoal {
    public static final String SCHEMA="hepta.web-shopping-goal.v1";
    public static final String KIND="mi_public_product";
    public static final String SITE_POLICY_ID="mi_cn_ax3000t_read_v1";
    public static final String MODEL_TERM="AX3000T";
    public static final String DISPLAY_MODEL="Xiaomi 路由器 AX3000T";
    public static final String LEGACY_EXPLICIT_OWNER=
            "在小米中国官方商城只读查询 Xiaomi 路由器 AX3000T 的单件配置，核对 Wi-Fi 6、3000M级、4个自适应WAN/LAN口，告诉我该配置当前公开的人民币价格，以及是否为起价、划线对比价、券后价或附带条件。不登录、不领券、不加购物车、不下单、不付款。";
    public static final Set<String> TOOL_CEILING=Collections.unmodifiableSet(
            new TreeSet<String>(Arrays.asList("open","click","back","scroll","wait","done")));
    private static final Pattern MODEL_FIRST=Pattern.compile(
            "^(?:请)?(?:帮我)?(?:查一下|查下|查询|查查|查看)(?:小米|Xiaomi)[ ]?(?:路由器[ ]?)?"
            +"(AX3000T)(?:的)?(?:官网|官方商城|中国官方商城)(?:售价|价格)[。？?]?$",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern STORE_FIRST=Pattern.compile(
            "^(?:请)?(?:帮我)?(?:查一下|查下|查询|查查|查看)(?:小米|Xiaomi)(?:中国)?(?:官网|官方商城)"
            +"[ ]?(?:路由器[ ]?)?(AX3000T)(?:的)?(?:售价|价格)[。？?]?$",
            Pattern.CASE_INSENSITIVE);
    private static final Set<String> FORBIDDEN=Collections.unmodifiableSet(new TreeSet<String>(
            Arrays.asList("login","register","consent_grant","coupon_claim","cart","order","payment",
                    "account_change","permission_change","arbitrary_app","arbitrary_url","arbitrary_js")));
    public final String owner,ownerSha256,contractSha256;
    public final String contractSchema=SCHEMA,providerSelection=KIND,recognition;
    public final int productStartUtf16,productEndUtf16;
    public final boolean naturalReadOnlyIntent,specificationsRequested,singleUnitRequested;
    private final Map<String,Object> immutableContract;
    private final String canonicalContract;

    private WebShoppingGoal(String raw,int start,int end,boolean natural) {
        owner=raw;ownerSha256=hash(raw);productStartUtf16=start;productEndUtf16=end;
        naturalReadOnlyIntent=natural;specificationsRequested=!natural;singleUnitRequested=!natural;
        recognition=natural?"bounded_natural_official_product_price.v1":"legacy_complete_explicit_product_read.v1";
        Map<String,Object> c=new LinkedHashMap<String,Object>();
        c.put("schema",SCHEMA);c.put("kind",KIND);c.put("owner_sha256",ownerSha256);
        c.put("owner_span_utf16",list(Integer.valueOf(0),Integer.valueOf(raw.length())));
        c.put("model_span_utf16",list(Integer.valueOf(start),Integer.valueOf(end)));c.put("model_term",MODEL_TERM);
        c.put("site_policy_id",SITE_POLICY_ID);c.put("market","mainland_china");
        c.put("purpose","public_product_price_information");c.put("natural_language_intent",Boolean.valueOf(natural));
        c.put("single_unit_requested",Boolean.valueOf(singleUnitRequested));
        c.put("specifications_requested",Boolean.valueOf(specificationsRequested));
        c.put("required_specifications",specificationsRequested?list("Wi-Fi 6","3000M级","4个自适应WAN/LAN口"):list());
        c.put("tool_ceiling",Collections.unmodifiableList(new ArrayList<String>(TOOL_CEILING)));
        c.put("forbidden_operations",Collections.unmodifiableList(new ArrayList<String>(FORBIDDEN)));
        c.put("preserve_price_conditions",Boolean.TRUE);c.put("visible_currency_required",Boolean.TRUE);
        c.put("same_product_context_required",Boolean.TRUE);c.put("navigation_from_observed_link_required",Boolean.TRUE);
        c.put("exact_variant_not_inferred",Boolean.TRUE);c.put("search_card_is_not_detail_result",Boolean.TRUE);
        immutableContract=Collections.unmodifiableMap(c);canonicalContract=canonical(c);contractSha256=hash(canonicalContract);
    }
    public static WebShoppingGoal parse(String raw) {
        if(!valid(raw))return null;
        if(LEGACY_EXPLICIT_OWNER.equals(raw)){
            int start=raw.indexOf(MODEL_TERM);return new WebShoppingGoal(raw,start,start+MODEL_TERM.length(),false);
        }
        Matcher match=MODEL_FIRST.matcher(raw);
        if(!match.matches()){match=STORE_FIRST.matcher(raw);if(!match.matches())return null;}
        return new WebShoppingGoal(raw,match.start(1),match.end(1),true);
    }
    /**
     * Lets the UI refuse/clarify an unsupported shopping-like OWNER instead of
     * silently falling back to generic application operation.
     * A true result is never authority and is not a successful parse.
     */
    public static boolean resemblesSupportedIntent(String raw) {
        if(!valid(raw))return false;
        return Pattern.compile("AX3000T",Pattern.CASE_INSENSITIVE).matcher(raw).find()
                &&(raw.contains("小米")||Pattern.compile("Xiaomi",Pattern.CASE_INSENSITIVE).matcher(raw).find())
                &&(raw.contains("官网")||raw.contains("官方商城"))
                &&(raw.contains("价")||raw.contains("购买")||raw.contains("下单"));
    }
    /** Intent only; original authority, current UI selection and lease are still required. */
    public boolean allowsInitialOfficialPage(){return true;}
    public Set<String> toolCeiling(){return TOOL_CEILING;}
    public Map<String,Object> contract(){return immutableContract;}
    public String canonicalContract(){return canonicalContract;}
    public static String contractHash(Map<String,Object> value){return hash(canonical(value));}
    public Map<String,Object> evidence() {
        Map<String,Object> observed=new LinkedHashMap<String,Object>();
        for(String key:Arrays.asList("product_id","selected_variant","quantity","price_raw","amount_decimal","currency","price_kind","committed_url"))
            observed.put(key,null);
        observed.put("product_result_verified",Boolean.FALSE);
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("schema",SCHEMA);out.put("kind",KIND);out.put("original_owner",owner);
        out.put("owner_sha256",ownerSha256);out.put("contract_sha256",contractSha256);out.put("contract",immutableContract);
        out.put("recognition",recognition);out.put("observed",Collections.unmodifiableMap(observed));
        out.put("original_owner_rewritten",Boolean.FALSE);out.put("task_authorization_compiled",Boolean.FALSE);
        out.put("grants_tool_authority",Boolean.FALSE);out.put("query_executed",Boolean.FALSE);out.put("business_verified",Boolean.FALSE);
        return Collections.unmodifiableMap(out);
    }
    private static List<Object> list(Object... values){return Collections.unmodifiableList(Arrays.asList(values));}
    private static boolean valid(String raw) {
        if(raw==null||raw.length()==0||raw.getBytes(StandardCharsets.UTF_8).length>1600)return false;
        for(int i=0;i<raw.length();i++){
            char c=raw.charAt(i);
            if(Character.isHighSurrogate(c)){if(++i>=raw.length()||!Character.isLowSurrogate(raw.charAt(i)))return false;}
            else if(Character.isLowSurrogate(c)||Character.isISOControl(c))return false;
        }
        return true;
    }
    /** Canonical JSON data encoding: UTF16-sorted object keys, ordered arrays, no floats. */
    private static String canonical(Object value) {
        if(value==null)return "null";
        if(value instanceof Boolean||value instanceof Integer||value instanceof Long)return value.toString();
        if(value instanceof String){
            String s=(String)value;StringBuilder out=new StringBuilder("\"");
            for(int i=0;i<s.length();i++){
                char c=s.charAt(i);
                if(Character.isHighSurrogate(c)){
                    if(i+1>=s.length()||!Character.isLowSurrogate(s.charAt(i+1)))throw new IllegalArgumentException("invalid Unicode");
                    out.append(c).append(s.charAt(++i));continue;
                }
                if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid Unicode");
                if(c=='\"'||c=='\\')out.append('\\').append(c);
                else if(c<0x20){String h=Integer.toHexString(c);out.append("\\u");for(int n=h.length();n<4;n++)out.append('0');out.append(h);}
                else out.append(c);
            }
            return out.append('\"').toString();
        }
        if(value instanceof List){
            StringBuilder out=new StringBuilder("[");List<?> a=(List<?>)value;
            for(int i=0;i<a.size();i++){if(i>0)out.append(',');out.append(canonical(a.get(i)));}return out.append(']').toString();
        }
        if(value instanceof Map){
            Map<?,?> map=(Map<?,?>)value;TreeSet<String> keys=new TreeSet<String>();
            for(Object key:map.keySet()){if(!(key instanceof String))throw new IllegalArgumentException("string map key required");keys.add((String)key);}
            StringBuilder out=new StringBuilder("{");int index=0;
            for(String key:keys){if(index++>0)out.append(',');out.append(canonical(key)).append(':').append(canonical(map.get(key)));}
            return out.append('}').toString();
        }
        throw new IllegalArgumentException("noncanonical contract type");
    }
    private static String hash(String raw) {
        try{
            byte[] bytes=MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder out=new StringBuilder(64);char[] hex="0123456789abcdef".toCharArray();
            for(byte b:bytes)out.append(hex[(b>>>4)&15]).append(hex[b&15]);return out.toString();
        }catch(NoSuchAlgorithmException impossible){throw new IllegalStateException("SHA-256 unavailable",impossible);}
    }
}

package org.trillionnium.hepta.webprotocol;

import org.json.JSONArray;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;

/** Shared immutable binding and exact canonical UTF-8 hash; no device effects. */
public final class WebEvidenceBinding {
    private WebEvidenceBinding() { }
    public static final String SCHEMA=WebEvidenceProtocol.BINDING_SCHEMA;
    private static final String[] FIELDS={"task_id","controller_session_nonce","owner","owner_sha256",
            "contract_sha256","authorization","background","controller_identity","helper_identity"};
    public static JSONObject fromAttach(JSONObject attach) throws Exception {
        WebTaskPurpose purpose=WebTaskPurpose.fromAttach(attach);
        JSONObject out=new JSONObject().put("schema",SCHEMA).put("initial_url",purpose.initialUrl)
                .put("goal_kind",purpose.kind).put("site_policy_id",purpose.sitePolicyId)
                .put("site_policy_sha256",purpose.sitePolicySha256);
        for(String key:FIELDS)out.put(key,attach.get(key));
        Object nonce=attach.get("controller_session_nonce");
        if(!(nonce instanceof String))throw new IllegalArgumentException("controller session nonce must be a string");
        out.put("storage_profile_name",WebStorageEvidence.profileFor((String)nonce));
        // The parse is a defensive deep copy. Per-request nonce/deadline are
        // deliberately not part of the stable lease identity.
        JSONObject copied=new JSONObject(canonical(out));WebTaskPurpose.requireBinding(copied);return copied;
    }
    public static String sha256(JSONObject binding) throws Exception {
        byte[] digest=MessageDigest.getInstance("SHA-256").digest(canonical(binding).getBytes(StandardCharsets.UTF_8));
        char[] hex="0123456789abcdef".toCharArray();StringBuilder out=new StringBuilder(64);
        for(byte b:digest)out.append(hex[(b>>>4)&15]).append(hex[b&15]);return out.toString();
    }
    /** Keys sorted by Java UTF-16 String.compareTo, arrays retain exact order. */
    public static String canonical(Object value) throws Exception {
        if(value==null||value==JSONObject.NULL)return "null";
        if(value instanceof String){
            String s=(String)value;StringBuilder out=new StringBuilder("\"");
            for(int i=0;i<s.length();i++){
                char c=s.charAt(i);
                if(Character.isHighSurrogate(c)){
                    if(i+1>=s.length()||!Character.isLowSurrogate(s.charAt(i+1)))throw new IllegalArgumentException("invalid Unicode");
                    out.append(c).append(s.charAt(++i));continue;
                }
                if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid Unicode");
                if(c=='\"'||c=='\\')out.append('\\').append(c);
                else if(c<0x20){String h=Integer.toHexString(c);out.append("\\u");for(int n=h.length();n<4;n++)out.append('0');out.append(h);}
                else out.append(c);
            }
            return out.append('\"').toString();
        }
        if(value instanceof Boolean)return value.toString();
        if(value instanceof Integer||value instanceof Long)return value.toString();
        if(value instanceof JSONArray){JSONArray a=(JSONArray)value;StringBuilder out=new StringBuilder("[");
            for(int i=0;i<a.length();i++){if(i>0)out.append(',');out.append(canonical(a.get(i)));}return out.append(']').toString();}
        if(value instanceof JSONObject){JSONObject o=(JSONObject)value;ArrayList<String> keys=new ArrayList<String>();
            Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);StringBuilder out=new StringBuilder("{");
            for(int i=0;i<keys.size();i++){if(i>0)out.append(',');String k=keys.get(i);out.append(canonical(k)).append(':').append(canonical(o.get(k)));}return out.append('}').toString();}
        throw new IllegalArgumentException("noncanonical binding type");
    }
}

