        for(int i=0;i<values.length;i++)if(values[i]!=null)
            rows.add(ax(id+"-value-"+i,"",values[i],"android.widget.TextView",new Rect(210,y+25,850,y+100),
                    false,true,path+"/"+i,"android.view.View"));
